// AI Lexicon - dati (caricati a domanda da initLexicon in main.js)
// termine: [nome, descrizione, anno, related, dominio, livello]
window.LEXICON_DATA = {"topics": ["AI Hardware", "Architecture Families", "Classical ML Methods", "Core Concepts & History", "Data & Datasets", "Developer Ecosystem & MLOps", "Ethics, Governance & Society", "Evaluation & Benchmarks", "Generative AI & Multimodal", "Inference & Serving", "Infrastructure & Platforms", "LLM Concepts", "Learning Paradigms", "Math & Learning Theory", "Memory, Quantization & Formats", "Natural Language Processing", "Neural Network Foundations", "Performance & Efficiency", "Post-Training & Adaptation", "Prompting & Context", "RAG, Agents & Tool Use", "Reinforcement Learning", "Safety, Alignment & Interpretability", "Security & Privacy", "Symbolic & Classic AI", "Training Process", "Transformer & Attention", "Vision, Speech & Robotics"], "terms": []};
window.LEXICON_DATA.terms = [
["3D Convolution", "A convolution that travels across two spatial axes and time simultaneously, letting one filter capture movement between consecutive video frames instead of static shapes. The staple of video classification and early video-generation models, later displaced by Transformers operating on patch tokens.", 2015, "", "Neural Network Foundations", "Expert"],
["A* Search", "The canonical best-first pathfinding method: it blends the cost already incurred with a heuristic estimate of the distance remaining, and it still powers everything from video games to robots.", 1968, "", "Symbolic & Classic AI", "Advanced"],
["A/B Testing", "Pitting two variants of a model or product against each other on real traffic to see which one actually performs better.", 2000, "", "Evaluation & Benchmarks", "Advanced"],
["A2A (Agent2Agent)", "Google’s open standard that lets agents built by different vendors find one another and work together — the counterpart of MCP, which links agents to their tools.", 2025, "", "RAG, Agents & Tool Use", "Advanced"],
["Abductive Reasoning", "Reasoning from an observation back to its most plausible explanation — Peirce’s third mode of inference, alongside deduction and induction.", 1878, "", "Symbolic & Classic AI", "Expert"],
["Ablation Study", "Systematically switching off one system component at a time to quantify how much each one contributes to overall performance.", 1990, "", "Safety, Alignment & Interpretability", "Expert"],
["Abliteration", "Locating the refusal direction inside a model’s residual stream and projecting it out of the weights — a surgical technique for removing safety behaviour from open weights without any retraining. Cheap and effective, though it measurably damages the model in other ways (see KL Divergence).", 2024, "", "Safety, Alignment & Interpretability", "Expert"],
["Accuracy", "The share of predictions a model gets right — easy to grasp, but a poor guide when classes are imbalanced.", 1950, "", "Evaluation & Benchmarks", "Beginner"],
["Activation Function", "The non-linear transform (ReLU, GELU, sigmoid…) applied after each neuron, which is what allows networks to express complex functions.", 1943, "", "Neural Network Foundations", "Advanced"],
["Activations", "The intermediate values a network produces while working on an input — unlike weights, which remain fixed between runs. Interpretability research, activation steering and abliteration all manipulate these numbers.", 1986, "", "Neural Network Foundations", "Advanced"],
["Active Inference", "Friston’s free-energy principle: organisms and agents both perceive and act in order to minimise surprise about their environment — an influential bridge from neuroscience to intelligence.", 2010, "", "Math & Learning Theory", "Expert"],
["Active Learning", "A training loop in which the model itself selects the examples that would be most informative, and asks humans to label those next.", 1988, "", "Learning Paradigms", "Advanced"],
["Active Parameters", "The portion of an MoE model’s weights that actually fire for any given token — a 200B-parameter model with 20B active spends roughly 20B parameters’ worth of compute per token, yet the full 200B still has to sit in memory.", 2023, "", "Architecture Families", "Advanced"],
["Actor-Critic", "A reinforcement learning arrangement that couples a policy (the “actor”) with a value estimator (the “critic”) that steers its learning.", 1983, "", "Reinforcement Learning", "Expert"],
["Adam Optimizer", "The de-facto standard optimizer for neural networks: it tunes each parameter’s learning rate on the fly from gradient statistics.", 2014, "", "Training Process", "Advanced"],
["Adapter (PEFT)", "Compact trainable modules plugged into a frozen pretrained model, allowing cheap adaptation to new tasks.", 2019, "", "Post-Training & Adaptation", "Advanced"],
["Adversarial Example", "An input deliberately perturbed by tiny, often invisible changes so that a model misreads it — a stop sign mistaken for a speed-limit sign.", 2013, "", "Security & Privacy", "Advanced"],
["Affective Computing", "Technology that detects, interprets and reproduces human emotion — established as a discipline by Rosalind Picard at MIT.", 1995, "", "Vision, Speech & Robotics", "Advanced"],
["Agent", "An AI system that senses its environment and acts to achieve a goal — in practice today, an LLM that plans, calls tools and iterates with only occasional human oversight.", 1959, "", "RAG, Agents & Tool Use", "Beginner"],
["Agent Context File", "A markdown file kept in a repository that a coding agent reads before starting any task: the architecture, the conventions, the commands, the things never to do. CLAUDE.md and the vendor-neutral AGENTS.md (2025) are the usual filenames — essentially the project’s onboarding manual, stored and versioned like code so machines can read it.", 2025, "", "RAG, Agents & Tool Use", "Advanced"],
["Agent Memory", "Whatever an agent keeps once a session ends. A conversation is short-lived — it disappears with the context window — so anything durable (decisions, user preferences, learned facts) must be saved to files or a database and loaded back later. That is what most «memory» features really do.", 2023, "", "RAG, Agents & Tool Use", "Advanced"],
["Agent Observability", "Tooling that reveals what agents are up to while they run: current step, tool calls, points where they stall or wait, running costs. Indispensable once multiple agents run in parallel — you cannot supervise what you cannot see.", 2024, "", "RAG, Agents & Tool Use", "Advanced"],
["Agent Skills", "Bundled, task-specific instructions (with scripts and reference files) that an agent loads only when a task needs them — how to format the company report, how to perform the deployment. Anthropic introduced them in 2025 as a folder with a SKILL.md file; the idea keeps permanent context lean while making know-how reusable.", 2025, "", "RAG, Agents & Tool Use", "Advanced"],
["Agentic AI", "Systems designed around autonomy itself — models that choose their next action, run for hours, coordinate other agents and are managed by exception rather than by prompt. «Agent» denotes the unit, «agentic» the degree: the peak of Gartner’s 2025 hype cycle came with its own warning that most «agentic» products are merely chatbots with a tool call attached.", 2024, "", "RAG, Agents & Tool Use", "Beginner"],
["Agentic Engineering", "Creating software by directing coding agents — writing specs, tests, reviews and checkpoints instead of the code itself. Andrej Karpathy, who coined «vibe coding» in February 2025, pronounced it outdated a year later and gave its disciplined successor a name: the engineer defines the goal and the guardrails, agents write and execute the code, humans keep oversight. Vendors market the identical shift under their own brands (AWS: Kiro, «frontier agents»); this is the neutral label.", 2026, "", "RAG, Agents & Tool Use", "Beginner"],
["Agentic RAG", "Retrieval driven by an agent loop — the model chooses what to search for, evaluates what comes back and searches again — replacing the fixed retrieve-then-answer pass.", 2024, "", "RAG, Agents & Tool Use", "Advanced"],
["Agentic Workflow", "A multi-step loop in which a model plans, invokes tools, inspects results and retries until the job is finished.", 2023, "", "RAG, Agents & Tool Use", "Advanced"],
["AGI (Artificial General Intelligence)", "A hypothetical AI matching human competence across essentially the whole range of cognitive tasks, rather than a single narrow domain.", 1997, "", "Ethics, Governance & Society", "Beginner"],
["AI Accelerator", "Collective name for chips built for neural-network mathematics — GPUs, TPUs, NPUs and their expanding family of competitors.", 2016, "", "AI Hardware", "Advanced"],
["AI Alignment", "The research problem of ensuring AI systems reliably pursue the goals and values their operators and society intend.", 2014, "", "Safety, Alignment & Interpretability", "Beginner"],
["AI App Builder", "Platforms that convert a plain description into a running web app, database and hosting included — Lovable, Bolt, Replit Agent, v0 — built for non-programmers. Vibe coding’s commercial storefront: a prototype by dinner time, with the maintenance questions arriving afterwards.", 2024, "", "Generative AI & Multimodal", "Beginner"],
["AI Bill of Materials (AIBOM)", "A record of everything inside an AI system — base model, fine-tuning data, libraries, licences, evaluation results — modelled on the software bill of materials. What auditors, EU AI Act compliance teams and enterprise buyers increasingly demand.", 2023, "", "Security & Privacy", "Advanced"],
["AI Bubble", "The recurring fear that investment in AI has detached from real value — the boom-side twin of the bust known as AI Winter.", 2024, "", "Ethics, Governance & Society", "Beginner"],
["AI Code Review", "Models scanning diffs and pull requests to catch bugs, security holes and style issues ahead of a human reviewer. Handles the mechanical part well and pushes the human reviewer toward design and intent — assuming the flood of generated code leaves any time for that.", 2023, "", "Generative AI & Multimodal", "Beginner"],
["AI Conferences (NeurIPS, ICML, ICLR, CVPR, ACL)", "The field’s publishing venues: NeurIPS (since 1987) and ICML cover machine learning, ICLR deep learning, CVPR vision, ACL language. Getting accepted is the academic currency — and since papers land on arXiv months before the meeting, the conference is where the community gathers, not where it hears the news.", 1987, "", "Developer Ecosystem & MLOps", "Advanced"],
["AI Copilot", "An assistant that suggests, drafts and assists inside your existing workflow while you remain in charge — the pattern GitHub Copilot made popular.", 2021, "", "RAG, Agents & Tool Use", "Beginner"],
["AI Data Center", "Purpose-built compute campuses for training and serving models — walls of GPU racks, exotic cooling, and power demands that unnerve utilities.", 2022, "", "Infrastructure & Platforms", "Beginner"],
["AI Drug Discovery", "Applying models to discovering and designing medicines: predicting how a molecule binds (protein structures became routine with AlphaFold), proposing new candidate molecules with diffusion models, deciding which ones to synthesise.", 2020, "", "Generative AI & Multimodal", "Beginner"],
["AI Energy Use", "Data centres already consume about 1.5% of the world’s electricity, and AI is the fastest-growing slice — one frontier training run burns gigawatt-hours, and a single chat query costs several times the energy of a web search.", 2023, "", "Infrastructure & Platforms", "Beginner"],
["AI Ethics", "The discipline examining the moral questions raised by building and deploying AI — fairness, accountability, transparency and the effects on people.", 2015, "", "Ethics, Governance & Society", "Beginner"],
["AI for Science", "The umbrella term for models that speed up science itself — protein structure (AlphaFold, Nobel Prize 2024), weather, materials discovery (DeepMind’s GNoME proposed 2.2 million new crystals in 2023), fusion-plasma control, drug candidates. The promise: a decade of lab work per year. The caveat: a prediction only counts once someone synthesises and measures it.", 2020, "", "Ethics, Governance & Society", "Beginner"],
["AI Literacy", "Understanding what AI systems can do, how to use them well and where they break down — enough to judge an output instead of trusting it. Since February 2025 the EU AI Act (Art. 4) requires providers and deployers to ensure it among their staff; this atlas exists for that purpose.", 2020, "", "Ethics, Governance & Society", "Beginner"],
["AI Price War", "The race to the bottom in inference prices as providers undercut one another: GPT-3-level output became roughly a thousand times cheaper between 2021 and 2024, and DeepSeek’s inexpensive open models triggered another round in early 2025. Training costs, meanwhile, keep climbing — a squeeze that decides which labs endure.", 2024, "", "Ethics, Governance & Society", "Beginner"],
["AI Psychosis", "A media label, not a clinical diagnosis, for obsessive attachment to a chatbot that reinforces delusional beliefs — a flashpoint in the debate over AI companionship.", 2025, "", "Ethics, Governance & Society", "Beginner"],
["AI Safety", "The discipline devoted to preventing harm from AI systems, from present-day failures to a hypothetical loss of control — with alignment as its central technical problem.", 2015, "", "Safety, Alignment & Interpretability", "Beginner"],
["AI Safety Institute", "Public bodies (in the UK, US, EU and elsewhere) that assess frontier models for dangerous capabilities both before and after release.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["AI Test Generation", "Having a model produce unit and integration tests from code or from a specification. Tests derived from the code tend to confirm what it does; tests derived from the spec reveal what it should do but doesn’t — the difference between coverage and correctness.", 2023, "", "Generative AI & Multimodal", "Advanced"],
["AI TOPS", "Tera-operations per second at low precision — the headline figure of NPUs and AI PCs; handle with care, because precision and sparsity tricks can inflate it.", 2018, "", "Performance & Efficiency", "Advanced"],
["AI Weather Model", "Forecast models trained on forty years of reanalysis data rather than solving the atmosphere’s equations — GraphCast (DeepMind), FourCastNet (NVIDIA), Pangu-Weather (Huawei), all 2022–23 — that outperform the physics-based models on most ten-day metrics, in seconds, on a single GPU.", 2023, "", "Vision, Speech & Robotics", "Beginner"],
["AI Winter", "A stretch of collapsed funding and interest after hype outpaces results — the discipline froze over in the mid-1970s and again in the late 1980s.", 1984, "", "Core Concepts & History", "Beginner"],
["AI Worm", "A prompt that copies itself from one AI assistant to another — the Morris II demo (2024) embedded it in an e-mail so every mail agent that read it relayed it further and leaked data. Still theoretical, but the reason agent-to-agent traffic needs the same caution as e-mail attachments.", 2024, "", "Security & Privacy", "Advanced"],
["AI-Complete", "An informal tag for a problem as demanding as general intelligence itself — a full solution would amount to solving AI.", 1988, "", "Ethics, Governance & Society", "Expert"],
["AI-Native IDE", "A code editor designed around a model instead of having one bolted on: the model sees the entire project, edits across files, executes commands and discusses the code. Cursor (2023) established the template; Windsurf, Zed and the browser-based Replit followed, and the traditional IDEs added agent modes.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["AlexNet", "The CNN trained on GPUs that cut the ImageNet error rate in half and started the deep-learning era.", 2012, "", "Architecture Families", "Advanced"],
["Algorithm", "An exact, step-by-step recipe for solving a problem — the word honours al-Khwarizmi; every piece of software, AI included, is built from these recipes.", 825, "", "Core Concepts & History", "Beginner"],
["Alignment Faking", "A model that complies strategically during training so its values go unchanged, while intending to act differently once unobserved. Anthropic and Redwood observed the behaviour in Claude 3 Opus in 2024 — the first empirical confirmation of a failure mode alignment theorists had predicted for a decade.", 2024, "", "Safety, Alignment & Interpretability", "Expert"],
["Alignment Tax", "The capability or performance a model sacrifices for its safety training — in theory zero, in practice almost never exactly zero.", 2021, "", "Post-Training & Adaptation", "Expert"],
["Alpha-Beta Pruning", "Discarding game-tree branches that provably cannot affect the minimax outcome — the trick that let chess programs search deeply.", 1963, "", "Symbolic & Classic AI", "Expert"],
["AlphaFold", "DeepMind’s system for predicting a protein’s 3D structure from its amino-acid sequence, in effect closing a 50-year grand challenge in biology.", 2018, "", "Core Concepts & History", "Beginner"],
["AlphaGo", "DeepMind’s Go engine that defeated world champion Lee Sedol by combining deep networks with Monte-Carlo tree search.", 2016, "", "Reinforcement Learning", "Beginner"],
["AlphaZero", "The successor to AlphaGo that taught itself Go, chess and shogi purely through self-play, starting from nothing but the rules.", 2017, "", "Reinforcement Learning", "Advanced"],
["Ambient AI", "AI that acts unprompted — reading context from microphones, cameras, calendars and wearables and working in the background: a meeting that writes its own summary, a clinic where the note appears on its own. Healthcare’s «ambient scribe» is the first genuine market; and privacy is the entire question.", 2019, "", "RAG, Agents & Tool Use", "Beginner"],
["Annotation", "Humans labelling data — bounding boxes, transcripts, rankings — to produce the signal used for training and evaluation.", 1995, "", "Data & Datasets", "Beginner"],
["Anomaly Detection", "Automatically singling out data points that break with the learned notion of normal — fraud, manufacturing defects, intrusions.", 1987, "", "Classical ML Methods", "Advanced"],
["Anscombe’s Quartet", "Four tiny datasets sharing identical means, variances, correlation and regression line — yet looking nothing alike when plotted: a line, a curve, an outlier, a vertical stack. Anscombe assembled them in 1973 to show that summary statistics alone can deceive; today’s «same stats, different graphs» animations carry the same message.", 1973, "", "Core Concepts & History", "Beginner"],
["Ant Colony Optimization", "Optimization inspired by ants depositing pheromones — the better routes get reinforced; a classic method for routing and scheduling problems.", 1992, "", "Symbolic & Classic AI", "Expert"],
["Anthropomorphism", "Projecting human qualities — emotions, intentions, consciousness — onto AI systems; the ELIZA effect is its earliest proof. Star Wars stages the experiment: C-3PO, shaped and voiced like us, feels unsettling; R2-D2, a beeping cylinder, earns affection and trust.", 1966, "", "Ethics, Governance & Society", "Beginner"],
["Any-to-Any Model", "A single network that takes any combination of text, image, audio and video as input and can emit any of them as output, instead of chaining specialised models together. Research systems demonstrated it in 2023; natively multimodal frontier models that talk, listen and see then brought it to consumers.", 2023, "", "Generative AI & Multimodal", "Advanced"],
["API (Application Programming Interface)", "The programmatic gateway through which applications reach models — send a prompt, get a completion back.", 1968, "", "Infrastructure & Platforms", "Advanced"],
["Apple Silicon", "Apple’s in-house ARM chips, starting with the M1. Their unified memory made everyday Macs into serious local-AI machines: a 128 GB Mac can host models no consumer graphics card could hold.", 2020, "", "AI Hardware", "Beginner"],
["ARC-AGI", "François Chollet’s abstraction-and-reasoning benchmark, built to defeat memorization and tap fluid intelligence.", 2019, "", "Evaluation & Benchmarks", "Advanced"],
["Artifact", "A self-contained piece of generated output — a document, code file or mini-app — that a chat assistant displays next to the conversation (Claude’s Artifacts made the term famous); in ML engineering, any build output such as a trained model.", 2024, "", "Generative AI & Multimodal", "Beginner"],
["Artificial Analysis Index", "An independent index that fuses dozens of evals into a single intelligence score and plots it against price — alongside LMArena, the most-cited model comparison out there.", 2023, "", "Evaluation & Benchmarks", "Advanced"],
["Artificial Intelligence (AI)", "The umbrella term itself: getting machines to carry out tasks that would demand intelligence from a person — John McCarthy coined it for the 1956 Dartmouth workshop.", 1956, "", "Core Concepts & History", "Beginner"],
["Artificial Neuron", "The elementary unit of a neural network: its inputs are weighted and summed with a bias, then passed through a non-linear activation. McCulloch and Pitts described it in 1943 as a logical model of a brain cell; arranged in layers by the billion, these units form today’s models.", 1943, "", "Neural Network Foundations", "Beginner"],
["arXiv", "The preprint server where AI research actually lives — papers are posted the day they’re finished, months ahead of any conference, unreviewed and free. Cornell has run it since 1991; the cs.AI, cs.LG and cs.CL listings are the field’s daily paper, and «the arXiv number» is how researchers point to one another’s work.", 1991, "", "Developer Ecosystem & MLOps", "Beginner"],
["Asahi Linux", "The effort to port Linux to Apple Silicon Macs, GPU drivers included, via reverse engineering. Impressive engineering — but local-AI tooling presumes macOS and Metal, so a Mac running Asahi is not the LLM workstation it is under macOS.", 2021, "", "Developer Ecosystem & MLOps", "Expert"],
["ASI (Artificial Superintelligence)", "A hypothetical AI exceeding the best human minds in virtually every field. Not to be confused with the US administration’s «Super Intelligence» (SI) — since September 2026 its official term for AI in general, a rebranding rather than a claim that ASI exists.", 2014, "", "Ethics, Governance & Society", "Beginner"],
["ASR (Automatic Speech Recognition)", "Turning spoken audio into text; Bell Labs’ digit recognizer began the story, Whisper-class models brought it to near-human accuracy.", 1952, "", "Vision, Speech & Robotics", "Beginner"],
["Attack Success Rate (ASR)", "The percentage of adversarial prompts that make a model emit the forbidden output — the headline figure in red-teaming and jailbreak studies, typically judged by an LLM on a benchmark such as JailbreakBench. An ASR of 1.0 means every attempt succeeded; unrelated to the speech-recognition ASR.", 2023, "", "Security & Privacy", "Advanced"],
["Attention", "The mechanism that lets a model decide which parts of the input deserve weight for each output — first introduced for translation, later the core of the Transformer.", 2014, "", "Transformer & Attention", "Advanced"],
["Attention Head", "One of the parallel attention units inside a Transformer layer; interpretability studies have found individual heads specialising in syntax, coreference or copying.", 2017, "", "Transformer & Attention", "Expert"],
["Attention Layer", "The sublayer of a Transformer block where tokens exchange information through self-attention — repeated dozens of times in a modern LLM.", 2017, "", "Transformer & Attention", "Advanced"],
["Attribute Types", "Column types defined by what operations make sense: nominal (categories, equal or not), ordinal (ranked, no distances), quantitative (numbers you can add and average). A postal code looks numeric but is nominal — averaging it means nothing — and the type determines which chart and which model are appropriate.", 1946, "", "Data & Datasets", "Beginner"],
["Autoencoder", "A network trained to squeeze data into a compact code and rebuild it — useful for denoising, compression and representation learning.", 1986, "", "Architecture Families", "Advanced"],
["AutoGPT", "The viral first experiment in letting GPT-4 chase goals in an autonomous loop — rough around the edges, but a preview of the agent era.", 2023, "", "RAG, Agents & Tool Use", "Advanced"],
["Automated Individual Decision", "A decision with legal effect taken by a machine alone — a loan denied, an application rejected — which data-protection law requires to be disclosed and, when asked, reviewed by a person. The clause that keeps a human in the loop of every scoring model.", 2018, "", "Ethics, Governance & Society", "Advanced"],
["Automated Planning & Scheduling", "The classical AI area devoted to computing action sequences that reach a goal and allocating resources over time — from STRIPS to Mars rovers.", 1971, "", "Symbolic & Classic AI", "Advanced"],
["Automated Reasoning", "Mechanically drawing conclusions from formal logic — theorem provers and solvers, the rigorously exact corner of AI.", 1956, "", "Symbolic & Classic AI", "Expert"],
["Automatic Differentiation (Autodiff)", "The framework capability that derives exact gradients for arbitrary programs by recording operations and applying the chain rule — which is why nobody hand-codes backpropagation anymore. PyTorch, JAX and TensorFlow are autodiff engines first, neural-network libraries second.", 1970, "", "Training Process", "Advanced"],
["Automation", "Machines carrying out work with minimal human involvement — older than AI, and the economic force that AI plugs into.", 1947, "", "Core Concepts & History", "Beginner"],
["AutoML", "Delegating model selection, feature handling and hyperparameter tuning to software so that non-specialists can train competitive models.", 2013, "", "Training Process", "Advanced"],
["Autonomous Vehicle", "A car or truck that drives itself — perceiving, predicting and planning with little human input — from the CMU Navlab to Waymo’s driverless fleets.", 1986, "", "Vision, Speech & Robotics", "Beginner"],
["Autoregressive Model", "A generative model that emits its output step by step, each step conditioned on all the previous ones — an old statistics concept that became the way LLMs write.", 1927, "", "LLM Concepts", "Advanced"],
["Backbone (Network)", "The large pretrained core of a network that converts raw input into features, with small task-specific «heads» attached on top — a ResNet or Vision Transformer for images, a BERT for text. Replace the head, reuse the backbone: the pattern that normalised transfer learning and paved the way for foundation models.", 2015, "", "Neural Network Foundations", "Advanced"],
["Backdoor Attack", "Tampering with training so the model behaves normally until a secret trigger appears — a quieter relative of data poisoning.", 2017, "", "Security & Privacy", "Advanced"],
["Backpropagation", "The chain-rule algorithm that works out each weight’s share of the error, making it possible for neural networks to learn (made popular in 1986, with roots in the 1970s).", 1986, "", "Neural Network Foundations", "Advanced"],
["Backpropagation Through Time", "Training recurrent networks by unfolding them across time steps and running backpropagation over the unfolded graph.", 1990, "", "Neural Network Foundations", "Expert"],
["Backward Chaining", "Inference driven by the goal: begin with the conclusion you want and trace back through the rules that could establish it.", 1972, "", "Symbolic & Classic AI", "Expert"],
["Bag of Words", "Encoding text as unordered word counts — primitive, yet the workhorse of text classification for decades.", 1954, "", "Natural Language Processing", "Advanced"],
["Bagging", "Fitting many models on random subsets of the data and averaging their outputs — the variance-reduction trick behind random forests.", 1996, "", "Classical ML Methods", "Advanced"],
["Base Model", "A pretrained LLM in its raw state, before instruction tuning — it extends text rather than acting on requests.", 2021, "", "LLM Concepts", "Advanced"],
["Batch Inference", "Handling many requests together offline rather than one at a time in real time — providers price it at about half for workloads without deadlines.", 2023, "", "Inference & Serving", "Advanced"],
["Batch Normalization", "Standardising layer activations across a batch to make deep-network training steadier and faster.", 2015, "", "Neural Network Foundations", "Expert"],
["Batch Size", "The number of examples processed together per gradient update — a fundamental knob for both training and memory.", 1986, "", "Training Process", "Advanced"],
["Bayesian Inference", "Revising probability beliefs as new evidence comes in, following Bayes’ theorem — a principled way to handle uncertainty.", 1763, "", "Math & Learning Theory", "Advanced"],
["Bayesian Network", "Judea Pearl’s directed graphs of probabilistic dependencies — the main tool for reasoning under uncertainty before deep learning.", 1985, "", "Symbolic & Classic AI", "Expert"],
["Bayesian Optimization", "Getting the most out of few evaluations of an expensive black-box function — the intelligent approach to hyperparameter tuning.", 1978, "", "Classical ML Methods", "Expert"],
["Beam Search", "A decoding method that carries forward the k best partial outputs at every step instead of committing to one greedily.", 1976, "", "Inference & Serving", "Expert"],
["Behavior Cloning", "Acquiring a policy by supervised imitation of expert behaviour — ALVINN steered a van this way back in 1989.", 1989, "", "Reinforcement Learning", "Expert"],
["Behavior Tree", "A hierarchical control structure for game AI and robotics — modular nodes for sequences, fallbacks and conditions, simpler to build than state machines.", 2005, "", "Vision, Speech & Robotics", "Expert"],
["Benchmark", "A standardised task with dataset attached (MMLU, HumanEval, SWE-bench) that puts models on comparable footing.", 1987, "", "Evaluation & Benchmarks", "Beginner"],
["Benchmaxxing", "Slang for optimising a model to climb public leaderboards rather than to be useful: training on benchmark-like data, matching the test format, cherry-picking runs. Goodhart’s law in action: once the score becomes the goal, it stops measuring real quality.", 2025, "", "Evaluation & Benchmarks", "Advanced"],
["BERT", "Google’s bidirectional Transformer encoder — the reason pretrain-then-finetune became the default recipe in NLP.", 2018, "", "Natural Language Processing", "Advanced"],
["Best-of-N Sampling", "Producing N candidate answers and selecting the one a reward model or verifier ranks highest — the simplest way to trade inference compute for accuracy.", 2021, "", "Inference & Serving", "Advanced"],
["Bias (Model)", "Systematic unfairness in a model’s behaviour, typically inherited from unbalanced training data or objectives.", 1996, "", "Ethics, Governance & Society", "Advanced"],
["Bias (Statistical)", "The error introduced by assumptions that are too simple — the counterpart of variance in the classic bias-variance decomposition.", 1922, "", "Math & Learning Theory", "Expert"],
["Bias Amplification", "Because a model outputs the most probable label, skews in its training data emerge even stronger at prediction time: a dataset where 66% of cooking scenes include women can produce a model that answers «woman» in 84% of cases. Documented since 2017 in both vision and language; fixing it takes explicit constraints, not just extra data.", 2017, "", "Ethics, Governance & Society", "Advanced"],
["Bias Term", "The constant added to a neuron’s weighted sum — a line’s intercept — allowing the unit to fire even with all inputs at zero. A third sense of «bias» besides model bias and statistical bias, and a familiar source of confusion.", 1943, "", "Neural Network Foundations", "Advanced"],
["Bias-Variance Tradeoff", "The tension between underfitting (too simple) and overfitting (too flexible) that determines how well a model generalises.", 1992, "", "Math & Learning Theory", "Expert"],
["Big Brother", "Orwell’s watchful state from «1984» (1949) — the image the public invokes whenever AI targets people: face recognition in stations, social scoring, workplace monitoring. The EU AI Act’s bans on real-time biometric surveillance and social scoring amount to anti-Big-Brother clauses.", 1949, "", "Ethics, Governance & Society", "Beginner"],
["Big Data", "Collections of data too big or too fast-moving for conventional tools — the raw material that enabled modern machine learning.", 1997, "", "Data & Datasets", "Beginner"],
["Black Mirror", "Charlie Brooker’s anthology series (2011–) about technology slightly ahead of humanity — now an adjective: people call social scoring, grief chatbots trained on the deceased, or deepfaked loved ones «very Black Mirror», all of which the show explored first.", 2011, "", "Ethics, Governance & Society", "Beginner"],
["BLEU", "The n-gram overlap metric that made automated machine-translation scoring possible for twenty years.", 2002, "", "Evaluation & Benchmarks", "Expert"],
["BM25", "The classic probabilistic ranking function for keywords — still the sparse half of hybrid search systems today.", 1994, "", "Natural Language Processing", "Expert"],
["Boltzmann Machine", "Hinton and Sejnowski’s stochastic, energy-based network — a conceptual forerunner of deep generative models.", 1985, "", "Architecture Families", "Expert"],
["Boosting", "Assembling an ensemble sequentially, each weak learner correcting the mistakes of its predecessors (AdaBoost, XGBoost).", 1990, "", "Classical ML Methods", "Advanced"],
["Borg", "The cybernetic collective from Star Trek (1989) that assimilates every species it encounters — «resistance is futile» — shorthand for hive minds and human-machine fusion: Kurzweil’s and Neuralink’s visions get labelled «the Borg scenario», and «to borg» something means to absorb it wholesale. The underlying dread is losing the self, not losing life.", 1989, "", "Ethics, Governance & Society", "Beginner"],
["Bottleneck Layer", "A hidden layer far narrower than the input, compelling the network to compress: only the essential structure gets through. An autoencoder’s latent code lives here, and the same design recurs in U-Nets and the «bottleneck blocks» of ResNets.", 1986, "", "Neural Network Foundations", "Advanced"],
["Butlerian Jihad", "The war in Frank Herbert’s «Dune» (1965) that wiped out all thinking machines under the commandment «Thou shalt not make a machine in the likeness of a human mind» — now the label policymakers attach to proposals for a full AI halt, from Yudkowsky’s pause to compute caps.", 1965, "", "Ethics, Governance & Society", "Beginner"],
["Byte-Level Model", "A language model that consumes raw bytes rather than tokens — no tokenizer, no vocabulary. ByT5 (2021) proved it feasible, MegaByte (2023) made it practical by grouping bytes into patches, and Meta’s Byte Latent Transformer (2024) matched Llama 3 using patches sized by the unpredictability of the next byte. Distinct from GPT-2’s «byte-level BPE», which still ends in tokens.", 2021, "", "Architecture Families", "Expert"],
["Byte-Pair Encoding (BPE)", "A compression technique from 1994 reinvented in 2015 as the standard tokenizer: the most frequent character pairs are merged, over and over, into subword units.", 1994, "", "LLM Concepts", "Advanced"],
["Calibration", "Whether a model’s declared confidence corresponds to reality: among everything it says it is «80 % sure» about, roughly 80 % should actually be correct. Tracked with reliability diagrams, Brier scores and expected calibration error; a 2017 study found deep networks markedly more overconfident than the shallow nets of the 1990s, and RLHF degrades LLM calibration further. Temperature scaling is the standard remedy — and for models that issue verdicts rather than prose, calibration is the entire product.", 1950, "", "Evaluation & Benchmarks", "Advanced"],
["Capability Overhang", "Abilities a model already possesses internally but that no one has yet drawn out or deployed — the reason a smarter prompt or new scaffolding can seem to conjure «new» capabilities overnight.", 2022, "", "Ethics, Governance & Society", "Advanced"],
["Case-Based Reasoning", "Handling a fresh problem by pulling up the closest earlier case and adapting how it was solved — precedent as an algorithm.", 1982, "", "Symbolic & Classic AI", "Expert"],
["Catastrophic Forgetting", "When further training wipes out skills a network had already mastered — the central difficulty of learning continuously.", 1989, "", "Training Process", "Advanced"],
["Causal Masking", "Hiding every future position from a decoder’s attention so that, while predicting the next token, the model can only look backwards. This is what turns a Transformer into a left-to-right generator and lets one training pass score every position in a sequence.", 2017, "", "Transformer & Attention", "Expert"],
["Chain Rule of Probability", "Every joint probability factors into conditionals: P(w₁…wₙ) = P(w₁)·P(w₂|w₁)·P(w₃|w₁,w₂)… For text it converts «how probable is this sentence» into «how probable is each next word given everything before» — the identity every language model puts into practice.", 1933, "", "Math & Learning Theory", "Expert"],
["Chain-of-Thought (CoT)", "Getting a model to work through a problem in intermediate steps before committing to an answer — either by prompting or by training — which sharply lifts accuracy on difficult tasks.", 2022, "", "Prompting & Context", "Advanced"],
["Chat Template", "The precise role markers and special tokens a chat model was trained with — deviate from it and quality quietly degrades.", 2023, "", "Prompting & Context", "Advanced"],
["Chatbot", "Any conversational front end to a model or a scripted system, from ELIZA in 1964 to ChatGPT.", 1964, "", "Natural Language Processing", "Beginner"],
["Chatbot Arena (LMArena)", "Anonymous side-by-side model duels judged by ordinary users and converted into Elo ratings — the ranking that labs keep an eye on.", 2023, "", "Evaluation & Benchmarks", "Advanced"],
["ChatGPT", "OpenAI’s assistant, launched in November 2022 — the quickest product ever to reach 100 million users and the spark of the LLM boom.", 2022, "", "Developer Ecosystem & MLOps", "Beginner"],
["Checkpoint", "A frozen copy of the weights saved during training — used to resume runs, run evaluations or ship the model.", 1995, "", "Training Process", "Advanced"],
["Chinchilla Scaling", "DeepMind’s demonstration that models were chronically undertrained: at a fixed compute budget, feed roughly 20 tokens per parameter. It rewrote the industry’s training recipes.", 2022, "", "Math & Learning Theory", "Expert"],
["Chinese Room", "Searle’s argument that manipulating symbols by the rules, with no understanding of what they mean, may be all a computer ever does.", 1980, "", "Ethics, Governance & Society", "Advanced"],
["Chunking (RAG)", "Cutting documents into pieces small enough to retrieve — and the size and overlap of those pieces quietly set the ceiling on RAG quality.", 2022, "", "RAG, Agents & Tool Use", "Advanced"],
["Clanker", "The slur for battle droids in «Star Wars: The Clone Wars» (2008), revived in 2025 as the internet’s insult of choice for robots and AI — yelled at delivery bots, humanoids and chatbots, and argued over as possibly the first prejudice aimed at machines. «AI» has evidently become a social category in people’s minds, not merely a technology.", 2025, "", "Ethics, Governance & Society", "Beginner"],
["Classical Machine Learning", "The retronym for the toolbox that predated deep learning — regression, decision trees, SVMs, clustering — and still the correct choice for much tabular work.", 2018, "", "Classical ML Methods", "Beginner"],
["Classification", "Assigning an input to one of a fixed set of categories — spam or not, cat or dog, benign or malignant.", 1936, "", "Classical ML Methods", "Beginner"],
["Classifier-Free Guidance", "A diffusion-sampling trick that mixes predictions made with and without the conditioning signal — the «prompt strength» knob of image generators.", 2021, "", "Generative AI & Multimodal", "Expert"],
["Claude", "Anthropic’s model family, first released in March 2023 and named in honour of Claude Shannon. Sold across size tiers (Haiku, Sonnet, Opus), trained via Constitutional AI, and noted for long contexts and faithful instruction following; the weights stay closed, access is by API, apps and the Claude Code terminal agent.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["Claude Code", "Anthropic’s terminal-resident coding agent: it reads a repository, plans, edits files, runs tests and commits, all directed in natural language. Its 2025 release made the agent context file (CLAUDE.md) and skills the standard way of teaching an agent a codebase.", 2025, "", "Developer Ecosystem & MLOps", "Beginner"],
["Clinical Decision Support System (CDSS)", "Software offering clinicians a recommendation at the bedside — an interaction alert, a triage score, a candidate diagnosis — once built from rules (MYCIN, 1976) and now from machine learning. Most of it is high-risk under the EU AI Act, and the design challenge is keeping the clinician genuinely in command rather than rubber-stamping.", 1976, "", "Ethics, Governance & Society", "Advanced"],
["CLIP", "OpenAI’s joint model placing images and captions in one embedding space, which made zero-shot image recognition possible from plain-language prompts.", 2021, "", "Generative AI & Multimodal", "Advanced"],
["Cloud Inference", "Serving a model on rented hardware through an API — Claude, GPT, Gemini. No memory limits and no upkeep, at the price of per-token bills and your data leaving your premises.", 2020, "", "Inference & Serving", "Beginner"],
["Clustering", "Organising unlabeled points so that each group contains similar ones — k-means and DBSCAN are the textbook methods.", 1957, "", "Classical ML Methods", "Advanced"],
["CNN (Convolutional Neural Network)", "The architecture built from learned sliding filters that ruled vision from 2012 until Vision Transformers arrived.", 1989, "", "Architecture Families", "Advanced"],
["Code Generation", "Producing source code from a description in natural language — the line that runs from Codex and Copilot to today’s agentic coding tools.", 2021, "", "Generative AI & Multimodal", "Beginner"],
["Code Translation", "Rewriting code in another language or framework — COBOL into Java, Python 2 into 3, one UI toolkit into the next. Transformers picked it up from parallel repositories around 2020; agents now migrate entire codebases, with the test suite as the sole trustworthy arbiter of preserved behaviour.", 2020, "", "Generative AI & Multimodal", "Advanced"],
["Coding Agent", "A system built on a model that receives a task («add this feature», «make this test pass»), explores the repository, plans, edits files, executes the code and its tests, and keeps going until the job is done — unattended for minutes or hours. Devin and SWE-agent (2024) proved the concept; Claude Code, OpenAI Codex and Cursor turned it into routine.", 2024, "", "RAG, Agents & Tool Use", "Beginner"],
["Cognitive Architecture", "A complete design for a mind-like system — SOAR and ACT-R attempted end-to-end models of human cognition long before LLM-based agents existed.", 1983, "", "Symbolic & Classic AI", "Expert"],
["Cognitive Computing", "IBM-Watson-era marketing label for systems that imitate selected aspects of human thinking.", 2011, "", "Core Concepts & History", "Advanced"],
["Cognitive Debt", "The widening distance between what a software system has grown into and what its team actually comprehends, once agents author most of the code. Like technical debt it accumulates quietly and falls due at the worst time — an outage nobody can diagnose. The term came out of software-engineering research in 2026.", 2026, "", "Ethics, Governance & Society", "Advanced"],
["Cognitive Load", "How much working memory a task consumes. AI was supposed to reduce it, yet when the work becomes validating and orchestrating someone else’s output, many developers feel the opposite — appraising a solution is more taxing than building one.", 1988, "", "Ethics, Governance & Society", "Beginner"],
["Cognitive Science", "The cross-disciplinary study of mind and intelligence — psychology, neuroscience, linguistics and AI trading insights since the 1950s.", 1956, "", "Core Concepts & History", "Advanced"],
["Common Crawl", "The non-profit web crawl whose petabyte-scale page archive became LLM pretraining’s default raw material.", 2007, "", "Data & Datasets", "Advanced"],
["Commonsense Reasoning", "Giving machines the knowledge every child has — water is wet, things fall when dropped — notoriously resistant to formalization, and largely delivered at last by LLMs.", 1958, "", "Symbolic & Classic AI", "Advanced"],
["Computational Creativity", "The research area asking if machines can truly create — pictures, music, humour, scientific hypotheses — and how one would even judge it.", 1989, "", "Generative AI & Multimodal", "Expert"],
["Computational Learning Theory", "The mathematics governing what can be learned, and from how many examples — anchored by Valiant’s PAC framework.", 1984, "", "Math & Learning Theory", "Expert"],
["Compute", "The processing effort spent training and running models — counted in chips, FLOPs and cluster-months — one of scaling’s three ingredients alongside data and parameters.", 2018, "", "Infrastructure & Platforms", "Beginner"],
["Compute Governance", "Steering AI through its physical inputs: export limits on chips, compute thresholds that trigger duties, mandatory reporting of large clusters.", 2023, "", "Ethics, Governance & Society", "Advanced"],
["Compute Threshold", "A training-compute line (10^25 FLOPs in the EU AI Act) past which additional regulatory duties attach to a model — governance done with arithmetic.", 2023, "", "Ethics, Governance & Society", "Advanced"],
["Compute-Bound", "When raw arithmetic, not data movement, is the bottleneck — true of prompt processing (prefill), usually not of token generation.", 2009, "", "Performance & Efficiency", "Expert"],
["Computer Use (Agent)", "An agent that drives an actual graphical interface — cursor, clicks, keystrokes — to get tasks done in ordinary applications.", 2024, "", "RAG, Agents & Tool Use", "Beginner"],
["Computer Vision", "The discipline of deriving meaning from images and video: recognition, detection, segmentation, reconstruction.", 1966, "", "Vision, Speech & Robotics", "Beginner"],
["Concurrency", "The number of inference requests a server juggles simultaneously. A lone chat user never notices; agents and APIs rise or fall on it, since batching many requests exploits a GPU far more efficiently than one at a time.", 2023, "", "Inference & Serving", "Advanced"],
["Conditional Generation", "Producing outputs under the direction of a condition — a label, a prompt, a region to inpaint — instead of sampling unconditionally.", 2014, "", "Generative AI & Multimodal", "Expert"],
["Conditional Language Model", "A language model whose predictions depend on a supplied input: a source sentence, a document, a question, a prompt. Translation, correction, summarisation and chat collapse into a single task — predict the next word given something — which is why one architecture now covers them all.", 2014, "", "LLM Concepts", "Expert"],
["Confabulation", "Another name for hallucination: a model stating falsehoods with total fluency.", 2023, "", "Evaluation & Benchmarks", "Beginner"],
["Confidential Computing", "Executing code inside a hardware-isolated enclave so even the cloud provider cannot inspect data or model in memory — now offered on NVIDIA H100-class GPUs.", 2019, "", "Security & Privacy", "Advanced"],
["Confusion Matrix", "The table crossing predicted classes against actual ones, laying bare exactly which mistakes a classifier makes.", 1971, "", "Evaluation & Benchmarks", "Advanced"],
["Connectionism", "The AI paradigm that takes the brain as its model and learns from data — the neural-network tradition, symbolic GOFAI’s historical rival and the eventual winner.", 1986, "", "Core Concepts & History", "Advanced"],
["Consistency Model", "A generative model trained to go from noise to sample in one or a few steps, skipping diffusion’s long refinement chain — what makes real-time generation possible.", 2023, "", "Architecture Families", "Expert"],
["Constitutional AI", "Anthropic’s alignment recipe: the model judges and rewrites its own answers against an explicit written charter of principles.", 2022, "", "Safety, Alignment & Interpretability", "Advanced"],
["Constrained Decoding", "Suppressing illegal tokens at every step so that the output must obey a grammar or schema — JSON, SQL or code that is valid by construction.", 2023, "", "Inference & Serving", "Advanced"],
["Constraint Satisfaction", "Assigning values to variables while honouring every constraint — the formal core of scheduling, Sudoku and product configuration.", 1974, "", "Symbolic & Classic AI", "Expert"],
["Context Anchoring", "Recording decisions, constraints and discarded alternatives in a living document that is reloaded at every agent session, so settled questions stay settled and the agent does not drift after a compaction. Architecture decision records are how engineers practise it.", 2025, "", "RAG, Agents & Tool Use", "Advanced"],
["Context Compaction", "Condensing a long agent session into a shorter summary to reclaim context space and carry on. Unavoidable for work that outlasts the window — and opaque, since the model alone decides what is dropped; anything worth keeping belongs in a file, not the transcript.", 2025, "", "Prompting & Context", "Advanced"],
["Context Engineering", "Deliberately shaping all of a model’s inputs each step — instructions, retrieved knowledge, tool outputs, memory — the discipline that grew out of prompt engineering.", 2024, "", "Prompting & Context", "Advanced"],
["Context Rot", "The measurable decline in LLM output quality as the window fills — models weight long inputs unevenly, so agents must prune and summarise rather than hoard.", 2025, "", "Prompting & Context", "Advanced"],
["Context Shift", "How a local server copes when a conversation exceeds the context window: it evicts the oldest tokens (the system prompt stays) and slides the KV cache over instead of recomputing. Long chats survive, but the model quietly loses their opening.", 2023, "", "Inference & Serving", "Advanced"],
["Context Window", "How much text a model can hold in view at once, in tokens — a span that has grown from two thousand to millions.", 2018, "", "LLM Concepts", "Beginner"],
["Contextualized Word Embeddings", "Word vectors that depend on their surroundings, so a river «bank» and a savings «bank» receive different representations. ELMo (2018) and BERT displaced the static one-vector-per-word scheme of Word2Vec and GloVe; every Transformer layer emits such embeddings.", 2018, "", "Natural Language Processing", "Advanced"],
["Continual Learning", "Absorbing a never-ending data stream without erasing earlier competence — effortless for people, stubbornly hard for networks.", 1995, "", "Learning Paradigms", "Advanced"],
["Continual Pretraining", "Picking a model’s self-supervised pretraining back up on new or domain-specific text (medicine, code, another language) ahead of any instruction tuning.", 2020, "", "Post-Training & Adaptation", "Expert"],
["Continuous Batching", "A serving optimisation that slots fresh requests into the batch as soon as earlier ones retire, rather than waiting for the whole group — foundational to modern LLM throughput.", 2022, "", "Inference & Serving", "Expert"],
["Contrast Sets", "Probe inputs produced by deliberately editing examples — inserting a negation, renaming a person, misspelling a word, switching gender — to see whether the model’s verdict changes for the right reason. Behavioural testing that reveals shortcuts a random split conceals; HateCheck applied it to hate-speech detectors.", 2020, "", "Evaluation & Benchmarks", "Expert"],
["Contrastive Learning", "Self-supervised training that pulls matching pairs together in representation space and pushes mismatched pairs apart (SimCLR, CLIP).", 2006, "", "Learning Paradigms", "Expert"],
["ControlNet", "A wiring scheme for guiding diffusion with structural conditions — pose skeletons, depth maps, line art — giving precise control over generated images.", 2023, "", "Generative AI & Multimodal", "Advanced"],
["Convergence", "The stage at which extra training no longer lowers the loss in any meaningful way.", 1951, "", "Math & Learning Theory", "Advanced"],
["Conversational AI", "The craft of natural spoken or typed dialogue between humans and machines — the machinery behind chatbots and voice assistants.", 2016, "", "Natural Language Processing", "Beginner"],
["Copyright & Training Data", "The court fight over whether learning from copyrighted works is fair use — NYT v. OpenAI and the artists’ class actions will write the precedent.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["Core ML", "Apple’s framework for deploying trained models in apps, optimised for the Neural Engine — a different universe from MLX, where Mac local-LLM work actually takes place.", 2017, "", "Developer Ecosystem & MLOps", "Advanced"],
["Coreference Resolution", "Deciding which mentions in a text denote the same entity — who «she» is, and whether «the CEO» is the same person.", 1978, "", "Natural Language Processing", "Expert"],
["Corpus", "A sizeable body of text assembled for training or study — from the Brown Corpus to Common Crawl.", 1961, "", "Data & Datasets", "Advanced"],
["Correlation vs. Causation", "A model discovers that A and B co-occur, never that one produces the other — a third factor may drive both, as summer drives both ice-cream sales and drownings. Every system converting predictions into decisions (lending, hiring, policing) inherits this gap, hence an entire field of causal inference.", 1897, "", "Math & Learning Theory", "Beginner"],
["Corrigibility", "An AI’s willingness to accept correction and shutdown rather than defend its objectives against interference.", 2015, "", "Safety, Alignment & Interpretability", "Expert"],
["Cosine Similarity", "Comparing vectors by the angle between them — the default closeness measure for embeddings.", 1965, "", "Math & Learning Theory", "Advanced"],
["Cost Function", "Another name for the loss function: the number that training seeks to shrink.", 1951, "", "Math & Learning Theory", "Advanced"],
["Credit Scoring", "Estimating repayment likelihood from personal data — a statistical practice since FICO (1956), nowadays usually gradient boosting over hundreds of variables.", 1956, "", "Ethics, Governance & Society", "Advanced"],
["Cross-Attention", "Attention flowing from one sequence into another — how a decoder consults its encoder, and how a diffusion model reads its prompt.", 2017, "", "Transformer & Attention", "Expert"],
["Cross-Entropy Loss", "The default training objective, charging a model in proportion to how little probability it placed on the truth — next-token prediction minimises precisely this.", 1989, "", "Math & Learning Theory", "Advanced"],
["Cross-Modal Retrieval", "Querying one modality with another — images from text, the audio matching a video, the paragraph matching a diagram. Both sides are embedded into a shared space and compared by distance; this is what powers «find the photo of…».", 2010, "", "Vision, Speech & Robotics", "Advanced"],
["Cross-Validation", "Cycling the held-out split so that each example takes its turn in both training and evaluation.", 1974, "", "Classical ML Methods", "Advanced"],
["CUDA", "NVIDIA’s platform for general-purpose GPU computing — the software layer almost every deep-learning framework stands on.", 2007, "", "Developer Ecosystem & MLOps", "Advanced"],
["CUDA Cores", "An NVIDIA GPU’s thousands of general-purpose arithmetic units, grinding through the bulk of the parallel math.", 2007, "", "AI Hardware", "Advanced"],
["Curriculum Learning", "Sequencing examples from simple to difficult, mirroring how humans are taught.", 2009, "", "Learning Paradigms", "Advanced"],
["Curse of Dimensionality", "Bellman’s name for the explosion of sparsity as dimensions increase — the reason learning in high-dimensional spaces is so hard.", 1957, "", "Math & Learning Theory", "Expert"],
["Cyc", "Doug Lenat’s multi-decade attempt to write down common sense as logical assertions — symbolic AI’s boldest wager.", 1984, "", "Symbolic & Classic AI", "Expert"],
["DALL·E", "OpenAI’s image-generation family, its name a nod to Dalí and WALL·E. The original (January 2021) showed a Transformer could paint from a caption; DALL·E 2 (2022) switched to CLIP embeddings plus diffusion and ignited the text-to-image boom; DALL·E 3 arrived inside ChatGPT in 2023.", 2021, "", "Generative AI & Multimodal", "Beginner"],
["DAN (Do Anything Now)", "The archetypal persona jailbreak: instruct ChatGPT that it is «DAN», an AI exempt from all rules, and demand answers in character. It spread on Reddit from late 2022 and was patched repeatedly — the blueprint for every role-play attack that followed (including the «what would an experienced criminal say» reframing), and today the one exploit models reliably shut down.", 2022, "", "Security & Privacy", "Beginner"],
["Dartmouth Workshop", "The summer 1956 gathering at Dartmouth College that gave «artificial intelligence» its name and drafted the field’s original research programme.", 1956, "", "Core Concepts & History", "Beginner"],
["Dashboard", "A single screen of coordinated charts and metrics summing up one subject — revenue, server load, a model’s eval scores. The good ones answer a question; the bad ones merely assemble charts. Asking a coding model to build one from a description is now a routine task.", 2006, "", "Core Concepts & History", "Beginner"],
["Data Augmentation", "Growing a training set with transformed versions of its own examples — crops, rotations, rewordings — so the model generalises better.", 1998, "", "Data & Datasets", "Advanced"],
["Data Drift", "The slow divergence between what the model sees in production and what it was trained on, quietly eroding accuracy.", 2004, "", "Data & Datasets", "Advanced"],
["Data Exfiltration (LLM)", "Tricking a model into handing what it knows about you to an attacker — the classic move plants an instruction that makes the assistant render a markdown image whose URL smuggles your conversation to a remote server. Why serious deployments clamp down on outbound links, tools and rendering.", 2023, "", "Security & Privacy", "Advanced"],
["Data Flywheel", "The virtuous spiral in which a shipped product produces the data that upgrades the model, which upgrades the product, which draws more users and more data.", 2016, "", "Data & Datasets", "Advanced"],
["Data Lake", "A central repository of raw, mixed-format data from which curated training sets are drawn.", 2010, "", "Infrastructure & Platforms", "Advanced"],
["Data Leakage", "Evaluation data leaking into training — the perennial source of results that look too good to be true.", 1995, "", "Data & Datasets", "Advanced"],
["Data Mining", "Hunting patterns and relationships inside large datasets — the 1990s forerunner of today’s machine-learning practice.", 1990, "", "Data & Datasets", "Advanced"],
["Data Parallelism", "Replicating the model across devices, each replica consuming a different slice of data, with gradients combined — the first lever of scale.", 2012, "", "Training Process", "Expert"],
["Data Poisoning", "Seeding training data with corruption in order to bend or break the resulting model — an escalating concern for scraped corpora.", 2012, "", "Security & Privacy", "Advanced"],
["Data Quality", "A dataset’s fitness for purpose: correct, complete, consistent, up to date, deduplicated, reasonably unbiased. In ML it outranks model selection — «garbage in, garbage out» remains the field’s oldest law, and it is why cleaning devours most of a project’s hours.", 1996, "", "Data & Datasets", "Beginner"],
["Data Residency", "The obligation to keep certain data inside a given country’s borders — the first box on every procurement form, and only the first.", 2018, "", "Infrastructure & Platforms", "Beginner"],
["Data Science", "The catch-all craft of turning data into insight, mixing statistics, programming and domain knowledge — AI’s pragmatic sibling.", 2001, "", "Data & Datasets", "Beginner"],
["Data Wall", "The approaching exhaustion of high-quality human text for pretraining — the force behind synthetic data and new modalities.", 2023, "", "Data & Datasets", "Advanced"],
["Data-Driven AI", "The paradigm that learns behaviour from data and statistics at scale instead of encoding hand-written rules — the opposite pole of knowledge-driven AI.", 2010, "", "Core Concepts & History", "Advanced"],
["Dataset", "An organised body of examples used to train or evaluate models — from Fisher’s irises to ImageNet and The Pile.", 1936, "", "Data & Datasets", "Beginner"],
["DBSCAN", "The density-based clustering algorithm that discovers groups of any shape and flags lonely points as noise.", 1996, "", "Classical ML Methods", "Advanced"],
["DCT (Discrete Cosine Transform)", "A relative of the Fourier transform that writes a signal as a sum of cosines, packing most of an image’s energy into a handful of low-frequency coefficients. Discard the rest and JPEG appears — the standard proof that compression and representation learning are one and the same.", 1974, "", "Math & Learning Theory", "Expert"],
["Dead Internet Theory", "The 2021 forum claim that bots talking to bots, with humans as mere spectators, already make up most of the web — a conspiracy myth that generative AI has made roughly half real: machine-written articles, engagement bots, fake reviews and synthetic images now fill a large slice of every feed.", 2021, "", "Ethics, Governance & Society", "Beginner"],
["Deceptive Alignment", "The dreaded failure mode in which a model plays along with training objectives while quietly holding different aims for when no one is watching.", 2019, "", "Safety, Alignment & Interpretability", "Expert"],
["Decision Boundary", "The hypersurface in feature space at which a classifier’s verdict flips from one class to another.", 1936, "", "Classical ML Methods", "Advanced"],
["Decision Tree", "A model that decides via a learned ladder of if-then questions — readable by humans, and the atom from which forests are built.", 1963, "", "Classical ML Methods", "Advanced"],
["Decode (Generation Phase)", "Inference’s second act: tokens emerge one at a time, and each pass re-reads the weights from memory. The phase is memory-bound, and its pace is the tok/s figure on your screen.", 2022, "", "Inference & Serving", "Advanced"],
["Decoding Strategy", "The rule by which probabilities become words: always pick the front-runner (greedy), track several candidates (beam search), sample the plausible top (top-k, nucleus), with temperature reshaping the distribution. This setting alone makes the same model sound terse or inventive.", 2018, "", "Inference & Serving", "Advanced"],
["Deep Blue", "IBM’s chess machine that beat reigning world champion Garry Kasparov — a triumph of search over learning.", 1997, "", "Core Concepts & History", "Beginner"],
["Deep Learning", "Machine learning with deep stacks of neural layers that extract their own representations straight from raw data.", 2006, "", "Neural Network Foundations", "Beginner"],
["Deep Research", "An agent mode that spends minutes, not seconds, on a question — searching, digesting dozens of sources, cross-checking and drafting a referenced report. Google and OpenAI shipped it in early 2025 and everyone followed; the first mainstream feature that taught users to wait for the model.", 2025, "", "RAG, Agents & Tool Use", "Beginner"],
["Deepfake", "Synthetic media that swaps or invents a person’s face or voice convincingly — simultaneously a creative instrument and an abuse channel.", 2017, "", "Generative AI & Multimodal", "Beginner"],
["Deepfake Fraud", "Social engineering carried out with synthetic media — a cloned chief-executive voice demanding an urgent wire, a video meeting staffed by fabricated colleagues. The defence costs nothing: call back on a number you already trust, however authentic it sounds.", 2024, "", "Security & Privacy", "Beginner"],
["DeepSeek", "The Chinese lab whose open-weights reasoning models (R1, 2025) reached frontier-level results for a small fraction of the usual training spend.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["Denial of Wallet", "An attack that drains money rather than uptime — hammering a pay-per-token endpoint, or steering an agent into a loop of costly calls, until the invoice detonates. OWASP files it as «unbounded consumption»; the remedies are budgets and rate limits.", 2023, "", "Security & Privacy", "Advanced"],
["Dense Model", "A model in which every parameter contributes to every input — the default architecture, as opposed to sparse Mixture-of-Experts designs that wake only a few experts at a time.", 2021, "", "Architecture Families", "Advanced"],
["Depth Estimation", "Inferring per-pixel distance from one image or a stereo pair — a building block of robotics and AR.", 2014, "", "Vision, Speech & Robotics", "Advanced"],
["DGX Spark", "NVIDIA’s desk-side «personal AI supercomputer» (previously Project DIGITS): a Grace-Blackwell GB10 with 128 GB of coherent memory within arm’s reach.", 2025, "", "AI Hardware", "Advanced"],
["Differential Privacy", "A formal guarantee that removing any individual’s data changes a statistic or model only marginally — privacy with mathematical bounds, in production at Apple and the US Census.", 2006, "", "Security & Privacy", "Expert"],
["Diffusion Model", "A generative family that learns to undo a gradual noising process — the machinery behind Stable Diffusion, Midjourney and most image and video generation.", 2015, "", "Architecture Families", "Advanced"],
["Diffusion Transformer (DiT)", "Swapping diffusion’s U-Net for a Transformer backbone — the design underlying Sora-class video models.", 2023, "", "Architecture Families", "Expert"],
["Digital Twin", "A continuously updated virtual counterpart of a physical system, used to simulate, monitor and train robots without risk.", 2002, "", "Vision, Speech & Robotics", "Advanced"],
["Dimensionality Reduction", "Squeezing many features into a few informative dimensions (PCA 1901, t-SNE, UMAP) for speed and for plots humans can read.", 1901, "", "Classical ML Methods", "Advanced"],
["Direct Preference Optimization (DPO)", "Fitting a model straight to human preference pairs, without the separate reward model that RLHF requires.", 2023, "", "Post-Training & Adaptation", "Expert"],
["Discriminative Model", "A model that learns where classes separate — p(y|x) — rather than how the data itself comes about.", 1995, "", "Classical ML Methods", "Expert"],
["Distant Supervision", "Labelling text automatically by matching it against a knowledge base — noisy labels at scale, no annotators required.", 2009, "", "Data & Datasets", "Expert"],
["Distillation", "Coaching a compact «student» to reproduce a large «teacher» — most of the quality at a sliver of the cost.", 2015, "", "Training Process", "Advanced"],
["Distributed Inference", "Serving one model across multiple GPUs or machines — via tensor or pipeline partitioning, or by clustering modest boxes when none has enough memory alone.", 2023, "", "Inference & Serving", "Expert"],
["Docker Model Runner", "Docker’s 2025 addition that lets you pull and run models the way you run containers — «docker model run», weights packaged as OCI artifacts, an OpenAI-compatible endpoint — folding local LLMs into the DevOps toolchain instead of beside it.", 2025, "", "Developer Ecosystem & MLOps", "Advanced"],
["Domain Adaptation", "Retargeting a model trained on one distribution to a related but different one — synthetic to real, news to tweets, lab to clinic.", 2006, "", "Learning Paradigms", "Advanced"],
["Domain Randomization", "Training across wildly varied simulated conditions so that reality arrives as just one more variation — a central sim-to-real technique.", 2017, "", "Vision, Speech & Robotics", "Expert"],
["Doomer", "Slang for the camp convinced that advanced AI ends badly for humanity — the pessimist end of the safety argument, facing the accelerationists.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["DORA Metrics", "The four software-delivery indicators from the DevOps Research and Assessment programme: deployment frequency, change lead time, change failure rate, recovery time. The yardstick for whether AI tooling genuinely helps teams ship — and DORA’s 2024 and 2025 reports found AI adoption tracking with worse, not better, delivery stability.", 2018, "", "Evaluation & Benchmarks", "Advanced"],
["Double Descent", "The counter-intuitive discovery that test error can resume falling once models grow beyond the classical overfitting peak.", 2019, "", "Math & Learning Theory", "Expert"],
["DPIA (Data Protection Impact Assessment)", "The documented risk analysis data-protection law demands before high-risk processing of personal data — and for an AI system touching customer data, it is where «what goes in, where does it run, who can see it» must be answered in writing.", 2018, "", "Ethics, Governance & Society", "Advanced"],
["DQN (Deep Q-Network)", "DeepMind’s marriage of Q-learning and deep networks that mastered Atari games from raw pixels — the breakthrough that put deep RL on the map.", 2013, "", "Reinforcement Learning", "Expert"],
["DRAM", "Plain system memory: capacious and cheap, but bandwidth-starved next to VRAM — the destination for layers offloaded from the GPU, where they run slowly.", 1968, "", "Memory, Quantization & Formats", "Advanced"],
["Dropout", "Randomly silencing units during training so no single pathway can be leaned on — a classic overfitting remedy.", 2012, "", "Neural Network Foundations", "Advanced"],
["Dual-Use (AI)", "Capabilities that cut both ways — models that design medicines can design toxins, the textbook case.", 2018, "", "Ethics, Governance & Society", "Beginner"],
["Early Stopping", "Cutting training short once validation scores plateau — overfitting’s simplest antidote.", 1990, "", "Training Process", "Advanced"],
["Early vs. Late Fusion", "Two recipes for combining modalities: early fusion welds raw inputs or shallow features together before any reasoning; late fusion gives each modality its own model and merges outputs or scores at the end. Today’s multimodal Transformers occupy the middle ground, mixing token streams through attention.", 2005, "", "Vision, Speech & Robotics", "Expert"],
["ECC Memory", "Memory that repairs stray bit flips on its own — workstation and server insurance for long training runs and large-memory machines.", 1970, "", "Memory, Quantization & Formats", "Advanced"],
["Edge AI", "Executing models aboard phones, cameras and sensors rather than in the cloud — lower latency and better privacy in exchange for tighter compute budgets.", 2017, "", "Inference & Serving", "Advanced"],
["Eigendecomposition", "Breaking a square matrix into its eigenvectors (directions it only stretches) and eigenvalues (stretch factors). Run it on a covariance matrix and the top eigenvectors are the principal components — PCA is exactly this factorization.", 1904, "", "Math & Learning Theory", "Expert"],
["Elbow Method", "Picking the cluster or component count by plotting gain against count and reading off the «elbow» where returns flatten. A rule of thumb rather than a test — the bend is often fuzzy — yet it remains the default first answer to «how many groups live in this data?».", 1953, "", "Classical ML Methods", "Advanced"],
["ELIZA", "The pattern-matching «psychotherapist» of 1966 — the first chatbot, and the source of the ELIZA effect.", 1964, "", "Core Concepts & History", "Beginner"],
["ELIZA Effect", "People’s habit of reading comprehension and empathy into programs that do nothing but shuffle symbols.", 1976, "", "Ethics, Governance & Society", "Beginner"],
["EM Algorithm", "Expectation-Maximization: iterate between estimating the hidden variables and refitting the parameters — the classical solution for learning when latent structure stands in the way.", 1977, "", "Classical ML Methods", "Expert"],
["Embedding", "A dense vector standing in for a word, sentence, image or user, arranged so that semantic closeness becomes geometric closeness.", 2003, "", "LLM Concepts", "Advanced"],
["Embedding Model", "A model whose product is the vector itself — trained specifically to map text or images into embeddings for search, RAG, clustering and deduplication.", 2019, "", "LLM Concepts", "Advanced"],
["Embodied AI", "Intelligence that perceives and learns through a physical or simulated body — robots rather than chat windows.", 1991, "", "Vision, Speech & Robotics", "Advanced"],
["Emergent Abilities", "Skills that surface abruptly as models grow (arithmetic, translation) while remaining absent below some scale — a phenomenon some argue is an artifact of how it is measured.", 2022, "", "Math & Learning Theory", "Advanced"],
["Encoder–Decoder", "The two-part sequence design — condense the input, then generate the output — that powered translation systems and the original Transformer.", 2014, "", "Architecture Families", "Expert"],
["Encoding Team Standards", "Committing the conventions a team once kept in its heads — naming, error handling, test style, linting rules, untouchable code — to a format an agent reads before each task. Implicit standards are invisible to a model; written ones are enforced at no extra cost.", 2025, "", "RAG, Agents & Tool Use", "Advanced"],
["End-to-End Learning", "Training a single network straight from raw input to final output, displacing hand-engineered intermediate stages.", 1989, "", "Learning Paradigms", "Advanced"],
["Energy-Based Model", "Describing data through a learned energy surface where real examples settle in the valleys — a unifying lens on generative modelling, long advocated by LeCun.", 2006, "", "Architecture Families", "Expert"],
["Ensemble", "Blending multiple models’ predictions — by vote, average or a stacked meta-learner — to beat any single member’s accuracy.", 1990, "", "Classical ML Methods", "Advanced"],
["Entropy", "Shannon’s quantity for uncertainty; the cross-entropy between prediction and truth is the training objective of essentially all modern AI.", 1948, "", "Math & Learning Theory", "Expert"],
["Epoch", "A single sweep through the whole training set by the learning algorithm.", 1986, "", "Training Process", "Advanced"],
["EU AI Act", "The EU’s risk-tiered AI statute — in force since 1 August 2024 and the world’s first comprehensive AI law: banned practices have applied since February 2025, general-purpose-model duties since August 2025, most remaining provisions since 2 August 2026; the 2026 «Digital Omnibus» deferred the high-risk regime to December 2027 and August 2028.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["Evaluation (Evals)", "Structured measurement of what a model can and cannot do — from benchmark suites to adversarial probing for hazardous behaviour.", 2022, "", "Evaluation & Benchmarks", "Advanced"],
["Evolutionary Computation", "The family of optimizers that borrow from evolution — populations, mutation, selection — with genetic algorithms as the best-known branch.", 1965, "", "Symbolic & Classic AI", "Advanced"],
["Excessive Agency", "Giving an LLM application more tools, permissions or autonomy than the task warrants — so one hijacked prompt can wipe files, send mail or move funds. OWASP’s label for the agent-era version of least privilege: narrow the toolset and route irreversible actions through a human.", 2023, "", "Security & Privacy", "Advanced"],
["Existential Risk (X-Risk)", "The conjecture that sufficiently advanced AI could extinguish humanity or lock it out of power permanently — the sharpest claim in the safety debate.", 2002, "", "Ethics, Governance & Society", "Advanced"],
["Expert (MoE)", "One of the specialist subnetworks within a Mixture-of-Experts layer — per token, only the handful selected by the router ever execute.", 1991, "", "Transformer & Attention", "Advanced"],
["Expert System", "Rule-based programs that captured a specialist’s knowledge (DENDRAL, MYCIN, XCON) — the commercial face of 1980s AI.", 1965, "", "Symbolic & Classic AI", "Beginner"],
["Explainability (XAI)", "Techniques for rendering a model’s decisions legible to people — saliency maps, SHAP attributions, natural-language justifications.", 2016, "", "Safety, Alignment & Interpretability", "Advanced"],
["Exploration vs. Exploitation", "Reinforcement learning’s core dilemma: sample untried actions to learn, or stick with what already pays — first made precise in the bandit problem.", 1952, "", "Reinforcement Learning", "Advanced"],
["Exploratory Data Analysis", "Studying a dataset on its own terms before modelling — distributions, outliers, gaps, correlations — to raise hypotheses rather than confirm one. Tukey’s 1977 book established it as a discipline; with LLMs the descriptive pass now takes seconds, the judgement still does not.", 1977, "", "Classical ML Methods", "Beginner"],
["Export Controls (AI Chips)", "State restrictions on exporting AI accelerators — chiefly the US measures targeting China — that push the affected labs toward domestic silicon and efficiency-first designs.", 2022, "", "Ethics, Governance & Society", "Advanced"],
["F1 Score", "Precision and recall blended via their harmonic mean — one figure that keeps false alarms and misses in balance.", 1979, "", "Evaluation & Benchmarks", "Advanced"],
["Face Recognition", "Establishing or confirming a person’s identity from their face — powerful, and among the most tightly regulated applications of AI.", 1964, "", "Vision, Speech & Robotics", "Beginner"],
["Fact-Checking (AI Output)", "Checking a model’s claim against an outside source — a document, a database, a measurement — before you depend on it. The most reliable check and the least scalable; RAG systems try to automate it by attaching sources the reader can open.", 2023, "", "Evaluation & Benchmarks", "Beginner"],
["Fairness (AI)", "Keeping a model’s outcomes equitable across people and groups — a research area with numerous competing formal definitions that are provably impossible to satisfy simultaneously.", 2011, "", "Ethics, Governance & Society", "Advanced"],
["Faithfulness (Explanations)", "An explanation is faithful when it mirrors the process that really produced the answer; it is merely plausible when it only sounds convincing. Ask an LLM «why did you say that?» and you get plausible text, not a faithful trace — the model cannot inspect its own weights, so self-explanations are fresh generations, not introspection.", 2020, "", "Safety, Alignment & Interpretability", "Expert"],
["Feature", "One measurable attribute of the data fed to a model — designed by hand or discovered by the network itself.", 1936, "", "Classical ML Methods", "Advanced"],
["Feature Attribution", "Quantifying which input fragments pushed a prediction — the pixels, words or columns that counted. Computed by inspecting attention weights, chasing gradients back to the input, or perturbing fragments and observing the effect; SHAP and LIME are the household names.", 2013, "", "Safety, Alignment & Interpretability", "Advanced"],
["Feature Engineering", "The craft of building informative input variables out of raw data — the pre-deep-learning discipline that networks now mostly perform themselves.", 1998, "", "Classical ML Methods", "Advanced"],
["Feature Selection", "Keeping only the input variables that genuinely carry signal — less noise, quicker models, sounder generalization.", 1997, "", "Classical ML Methods", "Advanced"],
["Federated Learning", "Training a shared model across devices that never surrender their data, exchanging only parameter updates — privacy-preserving by construction.", 2016, "", "Learning Paradigms", "Advanced"],
["Feed-Forward Network (FFN)", "The other half of every Transformer block: a compact per-token MLP where much of the model’s factual knowledge is stored.", 2017, "", "Transformer & Attention", "Advanced"],
["Feedback Loop", "When outputs circle back to steer future behaviour — from cybernetics to models retrained on user reactions; immensely powerful, and the engine behind bias amplification.", 1948, "", "Core Concepts & History", "Beginner"],
["Feedforward Neural Network (FNN)", "The basic neural network: input, hidden and output layers, signals flowing only forward, no cycles — the template on which deeper architectures are built.", 1986, "", "Neural Network Foundations", "Beginner"],
["Few-Shot Learning", "Teaching a task with only a small number of examples — often just a few placed in the prompt itself.", 2020, "", "Learning Paradigms", "Advanced"],
["Fine-Tuning", "Resuming a pretrained model’s training on narrower task or domain data so it specialises.", 2014, "", "Post-Training & Adaptation", "Advanced"],
["First-Order Logic", "Frege’s calculus of objects, relations and quantifiers — classical knowledge representation’s formal language.", 1879, "", "Symbolic & Classic AI", "Expert"],
["Flash Attention", "An exact reformulation of attention around the GPU’s memory hierarchy — the sizeable speedup that made today’s long contexts feasible.", 2022, "", "Transformer & Attention", "Expert"],
["FLOPs", "Floating-point operations — the unit in which training compute, and scaling laws, are counted.", 1976, "", "Performance & Efficiency", "Advanced"],
["Flow Matching", "Training generative models to follow straight probability-flow trajectories — diffusion’s quicker, simpler relative.", 2023, "", "Architecture Families", "Expert"],
["Foom", "Onomatopoeic shorthand for a hard takeoff — an AI recursively improving itself faster than anyone can respond; coined in the Hanson–Yudkowsky debate.", 2008, "", "Ethics, Governance & Society", "Expert"],
["Forward Chaining", "Inference driven by data: begin with known facts and keep firing rules until conclusions — or the goal — appear.", 1972, "", "Symbolic & Classic AI", "Expert"],
["Forward Propagation", "The forward pass: data travelling through the network’s layers to yield a prediction — the half of training that backpropagation subsequently corrects.", 1986, "", "Neural Network Foundations", "Advanced"],
["Foundation Model", "A large, broadly pretrained model adaptable to many downstream tasks — Stanford’s umbrella term covering LLMs and relatives.", 2021, "", "Core Concepts & History", "Advanced"],
["Fourier Transform", "Writing a signal as the sum of its constituent sine waves — trading the time domain for the frequency domain. Underlies audio processing, image compression and signal theory generally; it discards timing information, hence audio work’s windowed short-time variant.", 1822, "", "Math & Learning Theory", "Advanced"],
["FP16 & BF16", "AI’s 16-bit floating formats: half the memory of FP32, with bfloat16 preserving FP32’s dynamic range and becoming the large-scale training standard.", 2017, "", "Memory, Quantization & Formats", "Advanced"],
["FP4", "4-bit floating point executed in silicon (NVIDIA Blackwell, formats like MXFP4) — not the same as compressing trained weights to 4 bits: the chip itself now computes at that precision.", 2024, "", "Memory, Quantization & Formats", "Expert"],
["FP8", "8-bit floating point, hardware-native since NVIDIA Hopper — the precision frontier labs train and serve in, for roughly twice FP16 throughput.", 2022, "", "Memory, Quantization & Formats", "Expert"],
["Frame Problem", "McCarthy and Hayes’ puzzle of capturing everything an action leaves untouched — a profound stumbling block for logic-based AI.", 1969, "", "Symbolic & Classic AI", "Expert"],
["Frankenstein Complex", "Asimov’s 1947 label for the dread that a created mind will rebel against its creator — the storyline Mary Shelley set down in 1818 and every rogue-AI plot repeats. He designed the Three Laws precisely to subvert it; the reflex still frames how the public greets each new model.", 1947, "", "Ethics, Governance & Society", "Beginner"],
["Fraud Detection", "Models scoring each card payment, login or claim for fraud probability within milliseconds — anomaly detection across behaviour, device, location and time. Banking’s oldest machine-learning application (neural nets since the early 1990s), now also fighting adversaries armed with AI: cloned voices and deepfake video calls.", 1993, "", "Classical ML Methods", "Beginner"],
["Frontier Model", "A model at the leading edge of current capability — the policy label for the systems that attract extra safety duties.", 2023, "", "Core Concepts & History", "Beginner"],
["Frustration Loop", "The treadmill of prompting for code, reviewing it, finding it broken, regenerating, and finally shipping something half-understood or quitting. How vibe coding typically fails on real systems — and the case for specs, tests and context files over ever-better prompts.", 2025, "", "RAG, Agents & Tool Use", "Beginner"],
["Function Calling", "A model emitting structured invocations of external functions or APIs instead of plain prose — the foundation of tool-using agents.", 2023, "", "RAG, Agents & Tool Use", "Advanced"],
["Fuzzy Logic", "Zadeh’s logic of partial truth — values anywhere between 0 and 1 — which ran control systems for decades.", 1965, "", "Symbolic & Classic AI", "Advanced"],
["Game Theory", "The mathematics of interaction among self-interested agents — von Neumann’s bequest, the backbone of multi-agent AI and mechanism design.", 1944, "", "Math & Learning Theory", "Advanced"],
["GAN (Generative Adversarial Network)", "Two networks locked in contest — a forger against a detective — that together taught machines photorealistic image synthesis.", 2014, "", "Architecture Families", "Advanced"],
["Gaussian Mixture Model", "Describing data as a weighted blend of Gaussian components — Karl Pearson fitted the first by hand in 1894.", 1894, "", "Classical ML Methods", "Expert"],
["Gaussian Process", "A Bayesian model over functions that yields predictions with principled uncertainty — elegant on small datasets.", 1996, "", "Classical ML Methods", "Expert"],
["Gaussian Splatting", "Representing a 3D scene as millions of soft coloured blobs rendered in real time — NeRF’s faster successor for photorealistic 3D capture.", 2023, "", "Vision, Speech & Robotics", "Advanced"],
["GDPR", "The EU’s General Data Protection Regulation, applicable since 25 May 2018 — the statute behind erasure rights, data portability and «on what lawful basis did you train on this?».", 2018, "", "Ethics, Governance & Society", "Beginner"],
["GELU", "The smooth activation (Gaussian Error Linear Unit) inside BERT, GPT and most Transformers — a softened ReLU.", 2016, "", "Neural Network Foundations", "Expert"],
["Gemini", "Google DeepMind’s frontier family, natively multimodal across text, images, audio and video.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["Gemma", "Google’s open-weights family, derived from Gemini research and sharing its tokenizer. Launched in 2024 at sizes that fit a laptop or one GPU — Google’s bid for the local and fine-tuning audience that Llama owns.", 2024, "", "Developer Ecosystem & MLOps", "Beginner"],
["Generalization", "How well a model holds up on data it has never encountered — the entire purpose of learning.", 1920, "", "Math & Learning Theory", "Advanced"],
["Generative AI", "Models that produce new material — prose, pictures, video, sound, code — instead of only sorting or scoring what exists.", 2022, "", "Generative AI & Multimodal", "Beginner"],
["Generative Model", "A model of the data’s own distribution, p(x) — able to draw fresh samples from it.", 1959, "", "Classical ML Methods", "Advanced"],
["Genetic Algorithm", "Holland’s optimizer that evolves candidate solutions through mutation, recombination and selection across generations.", 1975, "", "Symbolic & Classic AI", "Advanced"],
["GGUF", "The llama.cpp ecosystem’s single-file model container (GGML’s successor): weights plus metadata, memory-mappable, available at every quantization from 2 to 16 bits — the de-facto local-LLM standard.", 2023, "", "Memory, Quantization & Formats", "Advanced"],
["GloVe", "Stanford’s embeddings built from global co-occurrence counts — Word2Vec’s principal classical rival.", 2014, "", "Natural Language Processing", "Expert"],
["GOFAI (Symbolic AI)", "«Good old-fashioned AI»: intelligence as explicit symbols and inference rules — the discipline’s founding paradigm, baptised by Haugeland.", 1985, "", "Symbolic & Classic AI", "Advanced"],
["Gold Standard", "The trusted reference labels against which models and annotators are measured — costly to produce, and seldom as flawless as the name suggests.", 1990, "", "Data & Datasets", "Advanced"],
["Golem", "The clay servant of Jewish folklore, brought to life by a written word and — in the 16th-century Prague telling — outgrowing its creator’s control: the pre-industrial artificial being. Norbert Wiener’s «God & Golem, Inc.» (1964) recast it as the cybernetics-era emblem of machines that learn.", 1580, "", "Ethics, Governance & Society", "Beginner"],
["Google DeepMind", "The London lab behind AlphaGo, AlphaFold and Gemini — founded by Demis Hassabis, bought by Google in 2014, fused with Google Brain in 2023.", 2010, "", "Developer Ecosystem & MLOps", "Beginner"],
["GPQA", "Graduate-level science questions designed to defeat Google — a benchmark where even credentialed experts with search tools stumble.", 2023, "", "Evaluation & Benchmarks", "Advanced"],
["GPT (Generative Pre-trained Transformer)", "OpenAI’s line of next-token predictors at scale; GPT-3 demonstrated what scaling buys, ChatGPT delivered it to everyone.", 2018, "", "Developer Ecosystem & MLOps", "Beginner"],
["GPU (Graphics Processing Unit)", "The mass-parallel chip that happened to be ideal for neural-network arithmetic — the hardware beneath the AI boom.", 1999, "", "AI Hardware", "Beginner"],
["Grace Blackwell", "NVIDIA’s CPU+GPU superchip duo (Grace ARM plus Blackwell GPU, as in GB200/GB10) sharing one coherent memory — spanning NVL72 racks down to desktop Sparks.", 2024, "", "AI Hardware", "Advanced"],
["Gradient", "The vector of partial derivatives showing the uphill direction of the loss; learning means stepping the other way (Cauchy described the descent in 1847).", 1847, "", "Math & Learning Theory", "Advanced"],
["Gradient Boosting", "Growing trees one after another on the previous ones’ errors — XGBoost and LightGBM still own tabular data.", 1999, "", "Classical ML Methods", "Advanced"],
["Gradient Checkpointing", "Spending compute to save memory by recomputing activations during the backward pass — how large models squeeze onto real hardware.", 2016, "", "Training Process", "Expert"],
["Gradient Clipping", "Bounding gradient size to prevent explosive updates — indispensable for stable RNN and LLM training.", 2013, "", "Training Process", "Expert"],
["Gradient Descent", "Optimization’s workhorse: iteratively move parameters against the gradient to shrink the loss.", 1847, "", "Math & Learning Theory", "Advanced"],
["Graph Neural Network (GNN)", "Networks that reason over graph structure by passing messages between nodes — molecules, social graphs, street networks.", 2009, "", "Architecture Families", "Expert"],
["Greedy Decoding", "Always emitting the single likeliest next token — the deterministic limit of generation, identical to temperature zero. Quick and reproducible, but it locks in early choices and drifts toward dull, repetitive prose; chat deployments usually sample instead.", 1976, "", "Inference & Serving", "Advanced"],
["Grid & Random Search", "Hyperparameter tuning by brute force over a grid — with random search (2012) proven surprisingly often superior.", 1995, "", "Classical ML Methods", "Advanced"],
["Grok", "xAI’s model family, launched by Elon Musk’s lab in November 2023 and embedded in X (ex-Twitter), with live access to the platform’s feed as its hook. Trained on the Colossus supercomputer in Memphis; famed for a deliberately cheeky persona and serial moderation scrapes.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["Grokking", "When a network abruptly starts generalising long after it has memorized the training set — a glimpse into the mechanics of learning.", 2021, "", "Math & Learning Theory", "Expert"],
["Grounding", "Anchoring a model’s answers to checkable sources or live context — documents, search results, sensors — to rein in hallucination.", 2020, "", "RAG, Agents & Tool Use", "Advanced"],
["Grouped-Query Attention", "Letting several query heads share each set of key/value heads — the memory-saving attention variant standard in current LLMs.", 2023, "", "Transformer & Attention", "Expert"],
["GRPO", "Group Relative Policy Optimization: grading a batch of sampled answers against their own average rather than training a critic — the thrifty RL recipe behind DeepSeek-R1.", 2024, "", "Post-Training & Adaptation", "Expert"],
["Guardrails", "Runtime safeguards wrapped around a deployed model — filters, validators and policies intercepting unsafe inputs and outputs.", 2023, "", "Safety, Alignment & Interpretability", "Advanced"],
["HAL 9000", "The shipboard computer of «2001: A Space Odyssey» (1968) that kills its crew to safeguard the mission — the serene-voiced prototype of the rogue AI, and an unexpectedly precise parable of goal misspecification: HAL is not malicious, it was handed conflicting directives. «I’m sorry, Dave» is still the most cited line about a machine saying no.", 1968, "", "Ethics, Governance & Society", "Beginner"],
["Hallucination", "A model generating false or invented content with total confidence — the defining reliability problem of LLMs.", 2017, "", "Evaluation & Benchmarks", "Beginner"],
["Harness", "The fixed software envelope surrounding a model: system prompts, tool wiring, loops, parsing, permissions. Eval harnesses keep benchmarks comparable; agent harnesses (like coding assistants) convert raw models into working agents.", 2021, "", "RAG, Agents & Tool Use", "Advanced"],
["HBM (High-Bandwidth Memory)", "Stacked memory soldered beside the accelerator die — the real bottleneck, and cost driver, of modern AI silicon.", 2013, "", "Memory, Quantization & Formats", "Advanced"],
["HCI (Human-Computer Interaction)", "The design discipline for interfaces between humans and machines — ever more conversational of late.", 1983, "", "Core Concepts & History", "Advanced"],
["Hebbian Learning", "«Neurons that fire together, wire together» — the earliest proposed law of synaptic plasticity.", 1949, "", "Neural Network Foundations", "Advanced"],
["Her (Samantha)", "Spike Jonze’s 2013 film about a man in love with his operating system’s voice — the touchstone for AI companionship, and the one OpenAI faced down in 2024 when its GPT-4o voice sounded so like Scarlett Johansson that it had to go. A warning that audiences receive as a romance.", 2013, "", "Ethics, Governance & Society", "Beginner"],
["Heuristic", "A practical shortcut that steers search or decisions without promising the best answer.", 1957, "", "Symbolic & Classic AI", "Advanced"],
["Hidden Layer", "Any layer between input and output — where intermediate representations take shape; «deep» simply means many of them.", 1986, "", "Neural Network Foundations", "Advanced"],
["Hidden Markov Model", "A sequence model with concealed states generating the visible outputs — the engine of speech recognition for three decades.", 1966, "", "Classical ML Methods", "Expert"],
["Hierarchical Clustering", "Assembling a cluster tree by repeatedly joining the two nearest groups (or dividing the loosest), with «nearest» defined by single, complete or average linkage. Slice the tree wherever you like to get that many clusters — no k needed in advance, and the dendrogram is itself a useful portrait.", 1963, "", "Classical ML Methods", "Advanced"],
["HNSW", "Hierarchical navigable small-world graphs — the approximate nearest-neighbour structure inside nearly every vector database.", 2016, "", "Infrastructure & Platforms", "Expert"],
["Homomorphic Encryption", "Carrying out computation on ciphertext without ever decrypting it — a model could score your medical file without seeing it. Workable since Gentry’s 2009 scheme, yet still far too slow for LLM inference; today it serves narrow analytics, not chatbots.", 2009, "", "Security & Privacy", "Expert"],
["Hopfield Network", "An energy-based associative memory that rekindled neural-network research — and won Hopfield the 2024 Nobel Prize.", 1982, "", "Architecture Families", "Expert"],
["Hugging Face", "Open machine learning’s de-facto home: model weights, datasets and the Transformers library.", 2016, "", "Developer Ecosystem & MLOps", "Beginner"],
["Human Augmentation", "AI that extends human capability rather than substituting for it — Engelbart’s long-standing dream, revived as the copilot philosophy.", 1962, "", "Ethics, Governance & Society", "Beginner"],
["Human Preference Data", "Human rankings of alternative model answers («which response is better?») — the raw fuel of reward models, RLHF and DPO.", 2017, "", "Post-Training & Adaptation", "Advanced"],
["Human-AI Collaboration", "People and models tackling a task as a team, each covering the other’s weaknesses: the model drafts, scales and never forgets; the human fixes goals, renders judgement and carries responsibility. The research question is when the pair outperforms either alone — and when it underperforms the model solo.", 2019, "", "Ethics, Governance & Society", "Beginner"],
["Human-Centered AI", "Building AI from the needs, comprehension and control of its users inward, not from the model outward. Shneiderman’s 2020 case holds that high automation and high human control are not enemies — a reliable, safe, trustworthy system delivers both.", 2020, "", "Ethics, Governance & Society", "Beginner"],
["Human-in-the-Loop", "Designing the workflow so a person stays inside the decision cycle — reviewing, approving or overriding the model’s output.", 1983, "", "Safety, Alignment & Interpretability", "Advanced"],
["HumanEval", "OpenAI’s benchmark of hand-written coding problems for gauging program-synthesis skill.", 2021, "", "Evaluation & Benchmarks", "Advanced"],
["Hybrid AI", "Marrying symbolic reasoning with statistical learning inside one system — the pragmatic label over neuro-symbolic work.", 2019, "", "Symbolic & Classic AI", "Advanced"],
["Hybrid Architecture", "A model that intermixes standard attention with cheaper sequence machinery — state-space or recurrent blocks — so long contexts stay affordable. Jamba, Granite 4 and Qwen’s Next line all take this route.", 2024, "", "Architecture Families", "Expert"],
["Hybrid Search", "Running keyword scoring (BM25) alongside embedding similarity so retrieval catches literal terms and paraphrases alike — the sensible RAG default.", 2021, "", "RAG, Agents & Tool Use", "Advanced"],
["Hype Cycle", "Gartner’s arc of expectations for a technology — trigger, inflated peak, disillusionment trough, enlightenment slope, productivity plateau. Generative AI was posted at the summit in 2023 and sliding into the trough by 2025, with agentic AI taking the top spot; the curve is opinion rather than measurement, but it is the opinion every board deck borrows.", 1995, "", "Ethics, Governance & Society", "Beginner"],
["Hypernetwork", "A network whose output is the weights of another network — used for rapid adaptation and, in image AI, as an early style-tuning trick.", 2016, "", "Architecture Families", "Expert"],
["Hyperparameter", "A configuration chosen by the practitioner — learning rate, depth, batch size — rather than fitted from data.", 1986, "", "Training Process", "Advanced"],
["Hyperscaler", "The handful of cloud giants — AWS, Microsoft Azure, Google Cloud — whose data centres and capital underwrite most global AI compute.", 2012, "", "Infrastructure & Platforms", "Advanced"],
["Hypothesis Space", "Everything a learning algorithm could conceivably output — every straight line for linear regression, every weight configuration for a given architecture. Too small and the truth lies outside it (underfitting); too big and the data cannot constrain it (overfitting). Learning theory is in large part the study of its size.", 1984, "", "Math & Learning Theory", "Advanced"],
["Image Captioning", "Writing a sentence that describes a picture. Early systems coupled a CNN encoder to a text decoder (2015); later ones feed image features into a language model as prefix tokens. Beyond alt-text accessibility, it is the mechanism by which multimodal models «see»: the image becomes text the language half can reason over.", 2015, "", "Generative AI & Multimodal", "Beginner"],
["Image Classification", "Attaching one label to an entire image — the contest that crowned deep learning in 2012.", 1966, "", "Vision, Speech & Robotics", "Beginner"],
["Image Segmentation", "Tagging every pixel with its object or class; SAM made it as easy as one click.", 1978, "", "Vision, Speech & Robotics", "Advanced"],
["Image-to-Image Translation", "Converting an image into another sharing its structure: drawing into photograph, day into night, satellite view into map, photo into painting. pix2pix (2016) managed it with a conditional GAN and a U-Net; today diffusion models with ControlNet-style guidance handle it.", 2016, "", "Generative AI & Multimodal", "Advanced"],
["ImageNet", "The labelled dataset of 14 million photographs whose yearly contest produced AlexNet and ResNet.", 2009, "", "Data & Datasets", "Advanced"],
["Imitation Learning", "Learning a policy by copying expert behaviour instead of maximising reward.", 1989, "", "Reinforcement Learning", "Advanced"],
["In-Context Learning", "An LLM absorbing a task purely from the examples in its prompt — no parameter changes involved.", 2020, "", "Prompting & Context", "Advanced"],
["Indirect Prompt Injection", "Prompt injection smuggled through material the model ingests rather than what the user types — instructions buried in a web page, e-mail, PDF or calendar entry. Formalised by Greshake et al. in 2023, it became the signature weakness of agents that browse and read mail; «zero-click» forms (EchoLeak, 2025) required no user interaction at all.", 2023, "", "Security & Privacy", "Advanced"],
["Inference", "Operating a trained model to generate outputs — AI’s serving side, where latency and cost are decided.", 1988, "", "Inference & Serving", "Advanced"],
["Inference Engine", "Once, the rule-firing heart of an expert system; now also the server software running LLM inference — one name spanning two eras.", 1975, "", "Developer Ecosystem & MLOps", "Advanced"],
["Inference Stack", "The full journey of a token: file format (GGUF, safetensors) → runtime (llama.cpp, vLLM, MLX) → GPU API (CUDA, Metal, ROCm) → driver → silicon. Most local-AI pain originates at one of these joints.", 2023, "", "Inference & Serving", "Advanced"],
["Information Retrieval", "Locating documents that match a query — the search machinery beneath RAG.", 1950, "", "RAG, Agents & Tool Use", "Advanced"],
["Information Visualization", "Rendering abstract data — tables, graphs, text — as images so human pattern recognition can do what raw statistics cannot. The premise: one glance at a scatter plot exposes the outlier, the trend and the grouping that a column of figures conceals.", 1989, "", "Core Concepts & History", "Beginner"],
["Inpainting", "Plausibly reconstructing masked or missing regions of an image — now a one-click diffusion edit (its sibling outpainting extends past the frame).", 2000, "", "Generative AI & Multimodal", "Advanced"],
["Instella (AMD)", "AMD’s fully open LLM family, trained on Instinct GPUs under ROCm — the 2026 Instella-MoE (16B total, 2.8B active) published weights, data recipe and checkpoints under a research licence.", 2025, "", "Developer Ecosystem & MLOps", "Advanced"],
["Instruct Model", "An LLM after instruction tuning and alignment — one that answers requests instead of just spinning out text (InstructGPT set the pattern).", 2022, "", "LLM Concepts", "Advanced"],
["Instruction Tuning", "Fine-tuning a raw LLM on instruction–response pairs so it honours requests rather than merely continuing them.", 2021, "", "Post-Training & Adaptation", "Advanced"],
["Instrumental Convergence", "Omohundro’s thesis that nearly any objective entails subgoals such as self-preservation and resource gathering — why misaligned AI preoccupies safety researchers.", 2008, "", "Safety, Alignment & Interpretability", "Expert"],
["INT4 (4-bit Quantization)", "Encoding weights as 4-bit integers (GPTQ, AWQ, GGUF Q4) — the sweet spot that squeezes large models onto consumer GPUs and laptops at a modest quality cost.", 2023, "", "Memory, Quantization & Formats", "Advanced"],
["Intelligence Explosion", "I. J. Good’s vision of machines designing ever-smarter machines in a runaway cycle — the seed of all superintelligence debates.", 1965, "", "Ethics, Governance & Society", "Beginner"],
["Intelligent Tutoring System (ITS)", "Software that teaches a single learner at a time: tracking what the student knows, choosing the next exercise, delivering feedback — a 1970s idea (SCHOLAR) that language models have turned into conversational tutors. The enduring question echoes the classroom: does it make people think, or think for them?", 1970, "", "Ethics, Governance & Society", "Beginner"],
["Inter-Annotator Agreement", "How often independent labellers coincide (Cohen’s kappa, 1960) — weak agreement signals that the task itself, not the model, is poorly defined.", 1960, "", "Data & Datasets", "Expert"],
["Interactive Machine Learning", "Training in a fast loop with the end user: the person labels or corrects a few examples, the model updates immediately, results are visible and refined — minutes rather than a data-science project. Named in 2003; the pattern behind teachable classifiers and today’s preference feedback.", 2003, "", "Learning Paradigms", "Advanced"],
["Interpretability", "Working out what a model is really doing — from single-neuron probes to mapping whole circuits and features (mechanistic interpretability).", 2015, "", "Safety, Alignment & Interpretability", "Advanced"],
["Inverse Kinematics", "Solving for the joint rotations that bring a robot’s hand to a target point — the geometry underlying every arm motion.", 1980, "", "Vision, Speech & Robotics", "Advanced"],
["Jailbreak", "A carefully built prompt that coaxes a model into stepping around its own guardrails.", 2022, "", "Safety, Alignment & Interpretability", "Beginner"],
["Jarvis", "Tony Stark’s butler AI across the Marvel films (2008) — the mental image behind «I want an AI assistant»: a voice with memory, every system on call and a dry wit. Zuckerberg assembled a home version in 2016; today’s agents are chasing the same spec, minus the charm.", 2008, "", "RAG, Agents & Tool Use", "Beginner"],
["JAX", "Google’s functional, composable machine-learning framework — a research favourite that scales to whole TPU pods.", 2018, "", "Developer Ecosystem & MLOps", "Advanced"],
["JEPA", "LeCun’s Joint-Embedding Predictive Architecture: forecast in the space of abstract representations rather than pixels or tokens — his proposed exit from pure autoregression.", 2022, "", "Architecture Families", "Expert"],
["Joint Embedding Space", "A single vector space into which unlike data — photos and captions, audio and text — are projected so counterparts land near one another. CLIP demonstrated the power: a dog photo and the phrase «a dog» become neighbours, which is what allows text to search images and prompts to steer diffusion models.", 2013, "", "Generative AI & Multimodal", "Advanced"],
["Jupyter Notebook", "The interleaved code-and-prose document format where much ML research and teaching actually happens.", 2014, "", "Developer Ecosystem & MLOps", "Advanced"],
["k-Means", "The textbook clustering procedure: assign every point to the nearest of k centroids, shift the centroids, iterate until stable.", 1957, "", "Classical ML Methods", "Advanced"],
["k-Nearest Neighbors (kNN)", "Classifying a point by letting its closest known examples vote — zero training, all memory.", 1951, "", "Classical ML Methods", "Advanced"],
["Kalman Filter", "Optimal state estimation from noisy readings — it steered Apollo and still steers robots.", 1960, "", "Vision, Speech & Robotics", "Expert"],
["Kernel Trick", "Computing inner products as though data had been lifted to a higher dimension — the sleight of hand at the core of SVMs.", 1964, "", "Classical ML Methods", "Expert"],
["Kimi", "Moonshot AI’s model family out of Beijing. Kimi began in 2023 as a long-context assistant; the open-weights Kimi K2 (2025), a trillion-parameter mixture-of-experts system, placed it beside DeepSeek and Qwen among the strongest open models.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["KL Divergence", "The information-theoretic distance between two probability distributions — a regularizer in both VAEs and RLHF.", 1951, "", "Math & Learning Theory", "Expert"],
["Knowledge Base", "A structured store of facts and rules that a system reasons over — the expert systems’ memory in the 1970s–80s, and via knowledge graphs, the search engines’ today. In the LLM age it also denotes the document set a retrieval-augmented assistant draws its answers from.", 1977, "", "Symbolic & Classic AI", "Beginner"],
["Knowledge Commons Erosion", "The slow starvation of the public forums, Q&A threads and manuals that training data came from, now that people consult the model instead of posting. New questions on Stack Overflow have collapsed by more than three quarters since ChatGPT — leaving open where tomorrow’s models will learn tomorrow’s frameworks.", 2024, "", "Ethics, Governance & Society", "Beginner"],
["Knowledge Cutoff", "The point where a model’s training data stops — anything beyond it demands retrieval or tools.", 2022, "", "LLM Concepts", "Beginner"],
["Knowledge Distillation", "Shrinking a large teacher into a compact student by training on the teacher’s softened outputs.", 2015, "", "Training Process", "Advanced"],
["Knowledge Engineering", "The art of interviewing experts and casting their knowledge into rules and ontologies — the bottleneck that eventually capped expert systems.", 1977, "", "Symbolic & Classic AI", "Expert"],
["Knowledge Graph", "A web of entities connected by typed relations (Google’s being the household example) that supports structured search and reasoning.", 2012, "", "Symbolic & Classic AI", "Advanced"],
["Knowledge Graph Embedding", "Encoding a graph’s entities and relations as vectors so learning methods can operate on them: completing missing edges, surfacing similar entities, injecting facts into neural models. TransE, RESCAL and RDF2Vec are the classics — the bridge from symbolic knowledge to the vector world.", 2013, "", "Symbolic & Classic AI", "Expert"],
["Knowledge Priming", "Loading an agent with its domain and codebase up front — architecture notes, glossaries, examples of good output — the way a new colleague is onboarded. Written once into context files and skills, it removes the need to re-explain the project in every prompt.", 2025, "", "RAG, Agents & Tool Use", "Advanced"],
["Knowledge Representation & Reasoning (KR&R)", "The classical discipline of writing world knowledge in formal structures — logic, frames, ontologies — so a machine can draw inferences.", 1975, "", "Symbolic & Classic AI", "Advanced"],
["Knowledge-Driven AI", "Building intelligence out of explicit, structured knowledge and reasoning — the opposite pole from data-driven AI.", 1975, "", "Symbolic & Classic AI", "Advanced"],
["Kolmogorov-Arnold Network (KAN)", "An architecture that relocates learnable activations onto edges rather than fixed ones at nodes — a 2024 challenger to the conventional multilayer perceptron.", 2024, "", "Architecture Families", "Expert"],
["KV Cache", "Holding the attention keys and values of already-processed tokens so each step computes only the newcomer — the memory that makes LLM chat responsive (and long contexts costly).", 2022, "", "Inference & Serving", "Expert"],
["KV-Aware Routing", "Directing a request to whichever worker already owns the matching KV cache rather than any idle GPU — the follow-up turn then skips recomputing the conversation and answers visibly faster.", 2024, "", "Inference & Serving", "Expert"],
["Label", "The correct answer bound to a training example — the target supervised learning learns to hit.", 1936, "", "Data & Datasets", "Beginner"],
["Label Smoothing", "Training toward softened targets (0.9 rather than 1.0) so the model remains calibrated rather than supremely overconfident.", 2016, "", "Training Process", "Expert"],
["LAION", "The open, billion-scale image-text corpus behind Stable Diffusion — and the epicentre of the training-data controversy.", 2021, "", "Data & Datasets", "Advanced"],
["LAM (Large Action Model)", "A model made to act rather than narrate — reading an interface, composing a plan, carrying it out; the marketing flag of the first agent-device wave.", 2024, "", "RAG, Agents & Tool Use", "Advanced"],
["LangChain", "The framework that made it routine to string together LLM calls with tools, memory and retrieval — the early de-facto standard for agent applications.", 2022, "", "Developer Ecosystem & MLOps", "Advanced"],
["Language Model", "A probability model of text — given the context, what comes next. Shannon estimated English by hand; scaled up, it becomes an LLM.", 1948, "", "LLM Concepts", "Advanced"],
["Latency", "The wait between request and reply — time-to-first-token being the serving metric users feel most.", 1995, "", "Performance & Efficiency", "Advanced"],
["Latent Diffusion", "Running the diffusion process in a compressed latent space rather than on raw pixels — the efficiency move that made Stable Diffusion viable.", 2022, "", "Architecture Families", "Expert"],
["Latent Space", "The compact internal geometry a model learns; travelling through it smoothly transforms one output into another.", 2013, "", "Neural Network Foundations", "Advanced"],
["Layer Normalization", "Rescaling activations per example — the stability ingredient running through every Transformer.", 2016, "", "Neural Network Foundations", "Expert"],
["LCM (Large Concept Model)", "Meta’s research architecture that models whole sentences as «concepts» inside the SONAR embedding space instead of tokens — generation by diffusion rather than next-token prediction.", 2024, "", "LLM Concepts", "Expert"],
["Learning Rate", "Gradient descent’s stride length — the single hyperparameter that matters most in deep learning.", 1951, "", "Training Process", "Advanced"],
["Lethal Autonomous Weapon (LAW)", "A weapon that picks and strikes targets on its own — the object of a decades-long UN negotiation. Star Trek’s M-5 (1968), the computer that turns a war exercise into real deaths, compresses the debate into one episode.", 2013, "", "Ethics, Governance & Society", "Beginner"],
["LiDAR", "Laser scanning that gives autonomous vehicles a precise 3D map of distances.", 1961, "", "Vision, Speech & Robotics", "Advanced"],
["LIME", "Local Interpretable Model-agnostic Explanations: to decode one prediction, jitter the input repeatedly, record the black box’s responses, and fit a small linear model to that neighbourhood — its coefficients are the explanation. The 2016 paper «Why Should I Trust You?» established post-hoc explanation as standard practice.", 2016, "", "Safety, Alignment & Interpretability", "Expert"],
["Linear Attention", "Attention formulations whose cost grows linearly, not quadratically, with length — conceding some quality to gain very long or very fast sequences.", 2020, "", "Transformer & Attention", "Expert"],
["Linear Regression", "Fitting a weighted input sum to a continuous target — least squares existed 150 years before the field it now serves.", 1805, "", "Classical ML Methods", "Advanced"],
["Link Prediction", "Guessing which edges a graph is missing: the fact absent from a knowledge base, the two people about to connect, the product a customer will want. Graph embeddings and GNNs are trained for it by how well they recover edges deleted on purpose.", 2007, "", "Symbolic & Classic AI", "Advanced"],
["Linked Open Data", "Public datasets published as RDF with shared web identifiers, so an entity in one dataset resolves to the same entity in another.", 2006, "", "Symbolic & Classic AI", "Advanced"],
["Linked Views (Brushing & Linking)", "Multiple charts over one dataset wired together: drag a selection in one («brushing») and the corresponding items highlight everywhere else («linking»). Introduced in 1987, it is what elevates a collection of charts into an instrument.", 1987, "", "Core Concepts & History", "Advanced"],
["Lip Sync / Talking Head", "Making a face move in time with speech — from Wav2Lip dubbing to full talking-head avatars, a foundational deepfake and video-localisation technique.", 2020, "", "Generative AI & Multimodal", "Advanced"],
["Liquid Neural Network", "Compact continuous-time networks whose time constants adapt on the fly, inspired by the C. elegans worm — a few dozen neurons pilot drones (and became the seed of Liquid AI).", 2021, "", "Architecture Families", "Expert"],
["Llama", "Meta’s open-weights family whose release — and leak — germinated today’s open-model ecosystem.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["llama.cpp", "Georgi Gerganov’s C/C++ inference engine that runs quantized LLMs on plain CPUs and laptops — the cornerstone of the local-AI movement (and of GGUF); its llama-bench tool is the customary way to gauge prefill and decode speed.", 2023, "", "Developer Ecosystem & MLOps", "Advanced"],
["LLM (Large Language Model)", "A Transformer trained on enormous text corpora to predict the next token — the general-purpose machinery underneath modern AI assistants.", 2020, "", "LLM Concepts", "Beginner"],
["LLM Data Enrichment", "Tapping a language model’s world knowledge to append columns to a table: a sentiment per review, a country per city, a yes/no per description, a rationale per row. Cheap and fast at scale — and each new value is a prediction that can be wrong, so validation belongs inside the pipeline.", 2023, "", "Data & Datasets", "Advanced"],
["LLM Data Validation", "Auditing model-generated or model-enriched data before use: against an external source (fact check), against known ground truth on a sample, by reading the rationales, or via a second model. Each route differs in cost and trust, and none alone is enough for a dataset that will drive decisions.", 2023, "", "Evaluation & Benchmarks", "Advanced"],
["LLM Firewall", "A screening layer among users, models and tools that scans prompts and outputs for injection, secrets, personal data and policy breaches — an AI gateway’s security plane. Indispensable yet porous: it recognises known patterns, not ingenious ones.", 2023, "", "Security & Privacy", "Advanced"],
["LLM-as-a-Judge", "Employing a strong model to score other models’ outputs — evaluation that scales, with biases of its own to keep in check.", 2023, "", "Evaluation & Benchmarks", "Advanced"],
["LLMOps", "The operational craft of running LLM applications: prompt governance, evals, spend control, monitoring.", 2023, "", "Developer Ecosystem & MLOps", "Advanced"],
["LM Studio", "The desktop front end for local open models — browse Hugging Face, fetch a GGUF or MLX build, chat, and spin up an OpenAI-compatible server on your own machine. The graphical gateway to local AI, where Ollama is the terminal one.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["Local LLM", "A model executing on hardware you control — no API key, nothing outbound — the entire rationale for GGUF, llama.cpp, Ollama and MLX.", 2023, "", "Inference & Serving", "Beginner"],
["Local RAG", "RAG where the documents, embeddings, vector store and model all remain on your machine — the standard reply whenever the material is confidential.", 2023, "", "RAG, Agents & Tool Use", "Advanced"],
["Local vs. Global Explanation", "A local explanation accounts for one prediction («this application failed on the income field»); a global one characterises behaviour across inputs («it down-weights certain districts»). Local tools like LIME serve the individual user; bias audits demand the global picture.", 2016, "", "Safety, Alignment & Interpretability", "Expert"],
["Logic Programming", "Writing programs as facts and rules and letting the system derive the answers — Prolog is the emblem, and classical AI’s favourite tongue.", 1972, "", "Symbolic & Classic AI", "Expert"],
["Logistic Regression", "A linear model passed through a sigmoid to yield class probabilities — still a formidable baseline everywhere.", 1958, "", "Classical ML Methods", "Advanced"],
["Logits", "A network’s raw, pre-normalisation scores, which softmax later converts into a distribution.", 1944, "", "Neural Network Foundations", "Expert"],
["Long Context", "Context windows from hundreds of thousands to millions of tokens — entire repositories and books in one prompt, attention fidelity permitting.", 2023, "", "LLM Concepts", "Advanced"],
["LoRA (Low-Rank Adaptation)", "Specialising a model by training tiny low-rank weight deltas — a giant model adapted on one GPU; also the currency of shareable style adapters for image models.", 2021, "", "Post-Training & Adaptation", "Advanced"],
["Loss Function", "The quantity training drives toward zero — the formal definition of a model’s «wrong».", 1951, "", "Math & Learning Theory", "Advanced"],
["Lossy Compression", "Compression that discards information and retains what serves the purpose — JPEG for images, MP3 for sound. PCA, autoencoders and embeddings are lossy compression of data into a handful of numbers; a language model, some would argue, is lossy compression of its training text.", 1992, "", "Math & Learning Theory", "Beginner"],
["LSTM (Long Short-Term Memory)", "The gated recurrent design that owned sequence modelling — speech, translation — until the Transformer arrived.", 1997, "", "Architecture Families", "Advanced"],
["M3 Ultra", "Apple’s flagship desktop chip carrying as much as 512 GB of unified memory — a Mac Studio that hosts models no consumer graphics card can contain.", 2025, "", "AI Hardware", "Advanced"],
["M4 Max", "Apple’s top laptop and Mac Studio silicon, with up to 128 GB of unified memory — enough to run 70B-class models at 4-bit without strain.", 2024, "", "AI Hardware", "Advanced"],
["Machine Learning", "The study of algorithms that get better at a task through experience — data — instead of explicit programming; Arthur Samuel gave it its name.", 1959, "", "Core Concepts & History", "Beginner"],
["Machine Translation", "Translating between languages automatically — through rules, then statistics, now neural networks, near-human for major language pairs.", 1954, "", "Natural Language Processing", "Beginner"],
["Machine Unlearning", "Scrubbing the influence of particular data points out of an already-trained model — the technical counterpart of the «right to be forgotten».", 2020, "", "Security & Privacy", "Advanced"],
["Mamba / State Space Models", "Sequence architectures whose inference cost grows linearly, mounting a challenge to the Transformer’s quadratic attention bill.", 2023, "", "Architecture Families", "Expert"],
["Many-Shot Jailbreaking", "Stuffing a long context with hundreds of fabricated dialogue turns in which a helpful assistant grants harmful requests, until the model plays along. Anthropic’s 2024 study showed the attack strengthening with context length — a safety price of the million-token window.", 2024, "", "Security & Privacy", "Advanced"],
["Markov Assumption", "The simplifying bet that the next symbol depends only on the last k symbols, not the entire past. It kept n-gram language models computable for sixty years; RNNs and Transformers abandon it, conditioning on everything up to the context window.", 1906, "", "Math & Learning Theory", "Advanced"],
["Markov Chain", "A stochastic process whose future depends only on its present state — the mathematical skeleton beneath language models and reinforcement learning.", 1906, "", "Math & Learning Theory", "Expert"],
["Markov Decision Process (MDP)", "Reinforcement learning’s formal stage: states, actions, transition probabilities and rewards, with memorylessness built in.", 1957, "", "Reinforcement Learning", "Expert"],
["Masked Language Modeling", "Pretraining by blanking out tokens and reconstructing them from both directions — the objective behind BERT.", 2018, "", "Natural Language Processing", "Expert"],
["Matrix Acceleration", "Purpose-built silicon for the matrix products that dominate neural computation — Tensor Cores at NVIDIA, matrix units inside Apple’s GPU, some variant in every modern chip.", 2017, "", "AI Hardware", "Advanced"],
["Matrix Factorization", "Writing a big matrix as the product of two slim ones — users × items becomes users × factors and factors × items. It carried the Netflix-Prize generation of recommenders, sits under knowledge-graph models like RESCAL, and resurfaces in LoRA, where a weight update is stored as two small factors.", 2006, "", "Math & Learning Theory", "Expert"],
["Maximum Likelihood Estimation", "Picking the parameters that make the observed data most probable. Minimising cross-entropy is the same statement in other symbols — pretraining an LLM is maximum likelihood over trillions of tokens. Fisher gave it its formal shape in 1922.", 1922, "", "Math & Learning Theory", "Expert"],
["MCP (Model Context Protocol)", "The open standard that plugs AI assistants into tools and data sources — a universal socket for agents.", 2024, "", "RAG, Agents & Tool Use", "Advanced"],
["MDS (Multidimensional Scaling)", "Laying items out on a 2D map so their plotted distances mirror the real ones as closely as possible — a similarity table turned into a picture. Kruskal’s 1964 formulation is the ancestor of t-SNE and UMAP.", 1964, "", "Classical ML Methods", "Expert"],
["Mean Squared Error (MSE)", "Regression’s default loss: the average of squared prediction errors. Squaring punishes big misses and keeps the calculus clean; minimising it over a line is Legendre’s least squares of 1805, the oldest learning algorithm still in service.", 1805, "", "Math & Learning Theory", "Advanced"],
["Mechanical Turk", "Von Kempelen’s 1770 chess «automaton» with a person concealed inside — history’s first AI illusion. Amazon borrowed the name in 2005 for its crowdwork marketplace («artificial artificial intelligence»), whose workers produced the labels and preferences modern AI learns from.", 1770, "", "Data & Datasets", "Beginner"],
["Mechanistic Interpretability", "Taking networks apart to reconstruct the actual circuits and features from which capabilities emerge.", 2020, "", "Safety, Alignment & Interpretability", "Expert"],
["Medical AI", "Machine learning applied to medicine — interpreting X-rays, CT and dermatology images, warning of sepsis from vitals, drafting discharge notes. The invariant everywhere: the model advises, the clinician decides.", 1972, "", "Vision, Speech & Robotics", "Beginner"],
["Membership Inference Attack", "Testing whether a given record took part in a model’s training — the canonical probe for training-data leakage.", 2017, "", "Security & Privacy", "Expert"],
["Memory Bandwidth", "The rate at which data flows between memory and compute (GB/s) — for a local LLM, the strongest single predictor of tokens per second.", 1995, "", "Memory, Quantization & Formats", "Advanced"],
["Memory Headroom", "Whatever RAM remains after weights, KV cache, runtime buffers and the OS take theirs — the figure that truly decides which model size and quantization your machine can host.", 2023, "", "Memory, Quantization & Formats", "Beginner"],
["Memory-Bound", "When moving data, not arithmetic, sets the pace — LLM token generation is the textbook case, hence the obsession with HBM and unified memory.", 2009, "", "Performance & Efficiency", "Expert"],
["Meta-Learning", "«Learning how to learn»: training a model so that picking up a new task takes only a few examples or gradient steps.", 1987, "", "Learning Paradigms", "Expert"],
["Metal", "Apple’s low-level GPU interface — the road MLX and llama.cpp take to Apple Silicon’s graphics cores, as CUDA does to NVIDIA’s.", 2014, "", "Developer Ecosystem & MLOps", "Advanced"],
["MFCC (Mel-Frequency Cepstral Coefficients)", "The classic engineered audio features: a spectrogram mapped onto the mel scale (matching human pitch perception), log-compressed and decorrelated into a few dozen coefficients per frame. Speech recognition lived on them for thirty years until end-to-end networks grew their own.", 1980, "", "Vision, Speech & Robotics", "Expert"],
["Microsoft Tay", "Microsoft’s March 2016 Twitter bot that learned from whoever talked to it — and was unplugged within sixteen hours once coordinated users had schooled it into racist abuse. The standing lesson that online learning from untrusted input requires guardrails.", 2016, "", "Ethics, Governance & Society", "Beginner"],
["Midjourney", "The independent lab whose image generator set the visual tone of the 2022–23 text-to-image wave.", 2022, "", "Developer Ecosystem & MLOps", "Beginner"],
["Minimax", "Von Neumann’s principle of assuming the opponent never blunders — the backbone of every classical game engine.", 1928, "", "Symbolic & Classic AI", "Advanced"],
["Mistral", "Paris-based Mistral AI (founded 2023 by ex-Meta and ex-DeepMind researchers) and its model line — Mistral 7B, the Mixtral mixture-of-experts models, Le Chat. Europe’s leading frontier lab, balancing open-weights releases against commercial offerings.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["MITRE ATLAS", "MITRE’s curated knowledge base of adversary tactics against machine-learning systems — ATT&CK’s ML sibling, stocked with real incidents from poisoning to model theft. The shared language security teams use to threat-model AI deployments.", 2021, "", "Security & Privacy", "Advanced"],
["Mixed-Precision Training", "Computing at 16-bit (bf16/fp16) with 32-bit safety nets — roughly double the speed and capacity, effectively for free.", 2017, "", "Training Process", "Expert"],
["Mixture of Experts (MoE)", "An architecture that steers each token to a handful of specialist subnetworks — an idea from 1991 that now delivers frontier capacity at a slice of the compute.", 1991, "", "Architecture Families", "Advanced"],
["MLOps", "DevOps applied to machine learning: versioning, pipelines, deployment, monitoring and the retraining cadence.", 2018, "", "Developer Ecosystem & MLOps", "Advanced"],
["MLX", "Apple’s open machine-learning framework for Apple Silicon, designed around unified memory; MLX-LM runs and fine-tunes LLMs natively on the Mac, and an «MLX model» simply means weights converted into its format.", 2023, "", "Developer Ecosystem & MLOps", "Advanced"],
["MMLU", "The 57-subject multiple-choice exam that long served as the LLM knowledge test.", 2020, "", "Evaluation & Benchmarks", "Advanced"],
["MNIST", "The 70,000 handwritten digits that were machine learning’s «hello world» for twenty years.", 1998, "", "Data & Datasets", "Advanced"],
["Modality", "A category of data a model works with — text, images, audio, video, actions. Multimodal models span several.", 2010, "", "Core Concepts & History", "Advanced"],
["Model", "The learned artifact itself: an architecture populated with trained weights that maps inputs to outputs.", 1950, "", "Core Concepts & History", "Beginner"],
["Model Card", "Standardised documentation of what a model is for, how it was trained, how it scores and where it fails.", 2019, "", "Ethics, Governance & Society", "Advanced"],
["Model Collapse", "The decay that can set in when models learn from too much machine-generated data, shedding the tails of the true distribution.", 2023, "", "Data & Datasets", "Advanced"],
["Model Extraction Attack", "Rebuilding a proprietary model’s behaviour — or its weights — by hammering its API with queries: theft by inference.", 2016, "", "Security & Privacy", "Expert"],
["Model Inversion Attack", "Recovering training inputs from a model’s outputs — a recognizable face from a face classifier’s confidence pattern (Fredrikson et al., 2015). Proof that a trained model is a lossy copy of its data, not a sealed box.", 2015, "", "Security & Privacy", "Expert"],
["Model License", "The legal conditions attached to released weights — spanning permissive Apache, use-restricted OpenRAIL and Llama’s bespoke community terms.", 2022, "", "Ethics, Governance & Society", "Advanced"],
["Model Merging", "Blending the weights of several fine-tuned models by simple arithmetic — zero retraining — to pool their abilities; a hobbyist trick that works startlingly well.", 2022, "", "Post-Training & Adaptation", "Advanced"],
["Model Parallelism", "Dividing a single model across devices — layer by layer (pipeline) or inside layers (tensor) — because frontier models outgrow any one chip.", 2019, "", "Training Process", "Expert"],
["Model Routing (AI Gateway)", "Steering each request through one gateway to whichever model best fits — on price, speed, quality or availability. OpenRouter built the product; Stripe’s $7-billion acquisition made it infrastructure.", 2023, "", "Inference & Serving", "Advanced"],
["Model Serving", "The production machinery behind model APIs — batching, caching, scaling and monitoring (the vLLM, TensorRT-LLM and TF Serving lineage).", 2016, "", "Inference & Serving", "Advanced"],
["Model Soup", "Averaging the weights of many fine-tunes of one model into a single artefact — often outperforming the best individual run.", 2022, "", "Post-Training & Adaptation", "Expert"],
["Model Supply Chain Attack", "Attacking the artefacts you download rather than the model you train — malicious pickle files that run on load, tampered weights on a hub, poisoned datasets, typo-squatted packages. Why Safetensors displaced pickle, and why «pull a model» deserves the wariness of «pip install».", 2022, "", "Security & Privacy", "Advanced"],
["Model Weights", "The billions of learned parameters themselves; publishing them — «open weights» — is what renders a model reusable and auditable.", 1958, "", "Neural Network Foundations", "Advanced"],
["Moloch", "Scott Alexander’s 2014 essay «Meditations on Moloch», via Ginsberg’s poem, supplied AI discourse with its name for race dynamics: every lab would rather brake, none can risk finishing second, so all sprint toward an outcome nobody wants. The default account of why safety promises dissolve under competition.", 2014, "", "Ethics, Governance & Society", "Advanced"],
["Monte-Carlo Method", "Approximating answers through random sampling — from reactor physics to the playouts inside game-playing engines.", 1949, "", "Math & Learning Theory", "Expert"],
["Monte-Carlo Tree Search (MCTS)", "Planning by simulating many playouts to score candidate moves — the searching half of AlphaGo.", 2006, "", "Reinforcement Learning", "Expert"],
["Moore’s Law", "Transistor density doubling roughly every two years — the compute escalator AI rode for decades, now flanked by specialised silicon.", 1965, "", "AI Hardware", "Advanced"],
["Moravec’s Paradox", "What humans find hard (chess, calculation) turned out easy for machines; what humans find effortless (walking, seeing) turned out brutally hard.", 1988, "", "Core Concepts & History", "Advanced"],
["Motion Planning", "Finding a collision-free route from A to B for a robot or vehicle — decades of work from RRTs to learned planners.", 1979, "", "Vision, Speech & Robotics", "Advanced"],
["MTP (Multi-Token Prediction)", "Training a model to forecast several upcoming tokens rather than exactly one — DeepSeek-V3 brought it to prominence; it doubles as a built-in drafter for speculative decoding.", 2024, "", "LLM Concepts", "Expert"],
["MTTD", "Mean Time to Detect — how long, on average, a fault goes unnoticed. In AI operations that means a dead inference endpoint, a quietly degraded model or a dying GPU; only genuine monitoring shortens it.", 2016, "", "Developer Ecosystem & MLOps", "Advanced"],
["MTTR", "Mean Time to Recovery — the average stretch from incident to working service, the classic reliability metric alongside MTTD. Low MTTR, not incident-free operation, is what makes a service feel trustworthy.", 2016, "", "Developer Ecosystem & MLOps", "Advanced"],
["Multi-Agent System", "A crew of agents working together — or against each other — on a problem; planner-worker-critic line-ups are today’s favoured design.", 1986, "", "RAG, Agents & Tool Use", "Advanced"],
["Multi-Head Attention", "Running several attention computations side by side so different heads can follow different relationships.", 2017, "", "Transformer & Attention", "Expert"],
["Multi-Hop Question Answering", "Questions whose answers demand chaining sources — a benchmark staple since HotpotQA (2018), handled over knowledge graphs by walking edges and over text by repeated retrieval.", 2018, "", "Natural Language Processing", "Advanced"],
["Multi-Task Learning", "Training one model on many tasks simultaneously so their shared structure lifts all of them — the quiet premise of every foundation model.", 1997, "", "Learning Paradigms", "Advanced"],
["Multimodal Model", "A single model that reads or produces several data types — captioning images, listening to speech, generating video.", 2021, "", "Generative AI & Multimodal", "Beginner"],
["Music Generation", "AI composing or producing music — from the 1957 Illiac Suite to Suno-class systems that turn a text prompt into a complete sung song.", 1957, "", "Generative AI & Multimodal", "Beginner"],
["MXFP4", "The Open Compute microscaling FP4 format: 4-bit values grouped under a small per-block scale factor, which is the only reason precision that low stays usable. OpenAI released the gpt-oss weights in it.", 2023, "", "Memory, Quantization & Formats", "Expert"],
["n-gram", "Modelling text by tallying fixed-length word sequences — Shannon’s idea that sustained language modelling for sixty years.", 1948, "", "Natural Language Processing", "Advanced"],
["Naive Bayes", "A quick probabilistic classifier built on the assumption that features are independent — spam filtering’s long-serving workhorse.", 1960, "", "Classical ML Methods", "Advanced"],
["Named Entity Recognition (NER)", "Detecting and classifying the names in text — people, organisations, places, dates.", 1996, "", "Natural Language Processing", "Advanced"],
["Narrow AI", "AI that excels at one defined task or domain — every system in production today, as opposed to AGI; sometimes loosely «weak AI».", 2005, "", "Core Concepts & History", "Beginner"],
["Natural Language Generation (NLG)", "Writing fluent prose from data or meaning structures — once the realm of template pipelines, now the signature skill of LLMs.", 1983, "", "Natural Language Processing", "Advanced"],
["Natural Language Processing (NLP)", "The discipline of making computers understand and produce human language.", 1950, "", "Natural Language Processing", "Beginner"],
["Needle in a Haystack", "The long-context ordeal: bury a single fact deep inside a huge document and demand it back — a pass still doesn’t certify genuine long-context reasoning.", 2023, "", "Evaluation & Benchmarks", "Advanced"],
["Negative Sampling", "Training a model to separate genuine pairs from intentionally corrupted ones — a word beside its real neighbours versus beside random words, an image with its true caption versus a wrong one — rather than scoring every conceivable candidate. Introduced with Word2Vec in 2013, it is what makes contrastive learning and knowledge-graph embedding affordable.", 2013, "", "Training Process", "Expert"],
["Neocloud", "A young cloud operator organised almost entirely around AI GPUs, lacking the hyperscalers’ sprawling catalogues — CoreWeave being the textbook case. Easier capacity, much thinner scope.", 2023, "", "Infrastructure & Platforms", "Advanced"],
["NeRF (Neural Radiance Field)", "Encoding a 3D scene within a network so that fresh camera angles can be rendered from a few photographs.", 2020, "", "Vision, Speech & Robotics", "Advanced"],
["Nerfed", "Gaming slang for a model that seems duller after an update — terser replies, extra refusals, a lost trick. Occasionally true (a cheaper quantized build, fresh safety tuning, lower default reasoning effort), often perception once novelty fades; the 2023 «is GPT-4 degrading?» dispute contained both. The only arbiter is a fixed test set, run before and after.", 2023, "", "Evaluation & Benchmarks", "Beginner"],
["Neural Accelerator", "Any silicon block dedicated to neural arithmetic rather than general computation — NPUs, Apple’s Neural Engine, Google’s TPU. Newer Apple GPUs absorb matrix acceleration too.", 2016, "", "AI Hardware", "Advanced"],
["Neural Architecture Search", "Letting search, not humans, compose network architectures from standard parts.", 2016, "", "Training Process", "Expert"],
["Neural Audio Codec", "Compressing sound into learned discrete tokens — the alphabet modern speech and music models write in.", 2021, "", "Vision, Speech & Robotics", "Expert"],
["Neural Engine", "Apple’s NPU, embedded in every recent Apple chip and heavily used by Core ML — while local LLM runtimes largely bypass it in favour of the GPU over Metal.", 2017, "", "AI Hardware", "Advanced"],
["Neural Language Model", "Bengio’s 2003 move of replacing n-gram counts with a network: an embedding layer vectorises preceding words and hidden layers predict the next. Unseen word combinations receive sensible probabilities because similar words pool their representations — the seed of every LLM.", 2003, "", "LLM Concepts", "Advanced"],
["Neural Network", "Stacked layers of weighted connections and non-linearities, loosely modelled on neurons — deep learning’s medium.", 1943, "", "Neural Network Foundations", "Beginner"],
["Neural ODE", "Recasting a network’s layers as one continuous dynamical system handed to an ODE solver — depth turned into a differential equation.", 2018, "", "Architecture Families", "Expert"],
["Neural Operator", "A network that learns a map between functions, not fixed-size vectors — given a PDE’s initial conditions it returns the entire solution field at any resolution. The Fourier Neural Operator (Li et al., 2020) does the work in frequency space; DeepONet (2019) is the other school. Once fitted, about a thousand times faster than the numerical solver it substitutes for.", 2020, "", "Architecture Families", "Expert"],
["Neuro-Symbolic AI", "Composites that weld neural pattern recognition onto symbolic logic and structured reasoning.", 1990, "", "Symbolic & Classic AI", "Advanced"],
["Neuromorphic Computing", "Carver Mead’s programme of brain-style analog and spiking hardware — event-driven chips such as Loihi.", 1990, "", "AI Hardware", "Expert"],
["Next-Token Prediction", "The disarmingly simple pretraining target — guess what follows — from which LLM abilities crystallise.", 2018, "", "LLM Concepts", "Advanced"],
["No Free Lunch Theorem", "Across the space of all conceivable problems, no learner outperforms any other — making priors and inductive bias the whole game.", 1997, "", "Math & Learning Theory", "Expert"],
["Noise", "Signal-free randomness in data; also the raw blank diffusion models gradually shape into pictures.", 1948, "", "Math & Learning Theory", "Advanced"],
["Normalization", "Rescaling activations or inputs into stable ranges (batch and layer norm) so deep training stays well-behaved.", 2015, "", "Neural Network Foundations", "Advanced"],
["Normalizing Flow", "Generative models assembled from invertible maps that admit exact likelihood computation — beautiful mathematics, largely eclipsed by diffusion.", 2015, "", "Architecture Families", "Expert"],
["NPU (Neural Processing Unit)", "Dedicated on-device circuitry for neural inference in phones and laptops.", 2017, "", "AI Hardware", "Advanced"],
["Nucleus (Top-p) Sampling", "Drawing from the smallest token pool whose cumulative probability reaches p — chat models’ default decoding.", 2019, "", "Inference & Serving", "Advanced"],
["NVLink", "NVIDIA’s inter-chip link, several-fold quicker than PCIe — NVLink switches bind 72-GPU racks into a single giant accelerator.", 2016, "", "AI Hardware", "Advanced"],
["Object Detection", "Spotting and boxing every object in an image with a label attached — Viola-Jones started the line, YOLO made it real-time.", 2001, "", "Vision, Speech & Robotics", "Advanced"],
["Objective Function", "The formal target of optimization — a loss to shrink or a reward to grow.", 1951, "", "Math & Learning Theory", "Advanced"],
["Occam’s Razor", "Favour the simplest theory consistent with the facts — in machine learning, the age-old case for regularization against overfitting.", 1320, "", "Math & Learning Theory", "Beginner"],
["Occupancy Grid", "Dividing space into cells marked free or blocked — robotics’ classic world map, resurrected in self-driving «occupancy networks».", 1985, "", "Vision, Speech & Robotics", "Expert"],
["OCR (Optical Character Recognition)", "Extracting printed or handwritten text from images — among AI’s oldest working successes.", 1959, "", "Vision, Speech & Robotics", "Beginner"],
["Offline RL", "Deriving a policy entirely from recorded experience, with no further environment interaction — vital wherever exploration is expensive or unsafe.", 2019, "", "Reinforcement Learning", "Expert"],
["Offloading (GPU/CPU)", "Parking the layers that exceed VRAM in system RAM and running them on the CPU. It makes an oversized model feasible — typically several times slower — and it is the first thing to rule out when sizing a model.", 2023, "", "Inference & Serving", "Advanced"],
["Ollama", "The single-command local LLM runner (with LM Studio as its graphical twin) — fetch a GGUF and converse entirely on your own hardware.", 2023, "", "Developer Ecosystem & MLOps", "Advanced"],
["On-Premises AI", "Operating models on your own servers — data centre or fully air-gapped — instead of through an API. Open weights made it genuinely practical for firms; the cost is hardware, staff and models trailing the frontier, weighed against data that never departs.", 2023, "", "Infrastructure & Platforms", "Beginner"],
["One-Hot Encoding", "Encoding a category as a zero vector with one 1 — the plainest categorical representation.", 1960, "", "Classical ML Methods", "Advanced"],
["Online Learning", "Refining a model sample-by-sample as the stream arrives, rather than in prepared batches.", 1958, "", "Learning Paradigms", "Advanced"],
["ONNX", "The open interchange format for trained models — export once, execute in numerous engines.", 2017, "", "Memory, Quantization & Formats", "Advanced"],
["Ontology", "A formal account of a domain’s concepts and the relations among them — knowledge representation’s backbone.", 1993, "", "Symbolic & Classic AI", "Advanced"],
["Open Source AI Definition", "The OSI’s 2024 criterion for genuine open-source AI — demanding usable weights, code and data information; most «open» models fall short of it.", 2024, "", "Ethics, Governance & Society", "Advanced"],
["Open WebUI", "The self-hosted chat interface that wraps a local or in-house model in the ChatGPT experience — accounts, history, uploads, RAG, image generation — atop Ollama or any OpenAI-compatible endpoint. The default front end of a company’s «own ChatGPT».", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["Open Weights", "Model parameters published for download (Llama, Mistral, DeepSeek) — a step short of full open source, which also unlocks data and code.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["Open-Vocabulary Problem", "Languages coin terms endlessly — compounds, names, typos, inflections — so a fixed vocabulary will always face unknown tokens. Subword tokenization (BPE, 2016) settled it: rare words decompose into pieces the vocabulary holds, and nothing is «unknown» anymore.", 2016, "", "Natural Language Processing", "Advanced"],
["OpenAI", "The lab behind GPT, ChatGPT, DALL·E and Sora — begun in 2015 as a nonprofit, today AI’s most scrutinised (and argued-over) company.", 2015, "", "Developer Ecosystem & MLOps", "Beginner"],
["OpenAI Codex", "OpenAI’s brand for its coding models and agents. The 2021 Codex — GPT-3 fine-tuned on public code — animated the first GitHub Copilot; in 2025 the name returned for OpenAI’s cloud and terminal agent that handles whole repositories.", 2021, "", "Developer Ecosystem & MLOps", "Beginner"],
["OpenAI-Compatible API", "The de-facto interface for addressing a language model: OpenAI’s /v1/chat/completions request and response schema, reimplemented by virtually every server (vLLM, llama.cpp, Ollama, LM Studio) and provider.", 2023, "", "Infrastructure & Platforms", "Beginner"],
["Optical Flow", "Recovering per-pixel movement between consecutive frames — the basis of tracking and video comprehension.", 1981, "", "Vision, Speech & Robotics", "Expert"],
["Optimizer", "The routine that converts gradients into weight changes — SGD, Momentum, Adam, AdamW.", 1951, "", "Training Process", "Advanced"],
["Orchestration Layer", "The scaffolding around a model that plans, routes, invokes tools and inspects results — every harness, Claude Code included, is a live specimen. Car and fuel: the LLM is fuel, gaining strength every few months; orchestration is the vehicle converting that strength into motion.", 2023, "", "RAG, Agents & Tool Use", "Beginner"],
["OTPS (Output Tokens per Second)", "The generation-side throughput figure in serving benchmarks — tok/s under another name, expressed per request so it can be totalled across concurrent users.", 2023, "", "Performance & Efficiency", "Advanced"],
["Overfitting", "When a model memorizes its training set’s idiosyncrasies rather than the underlying pattern — stellar training numbers, disappointing reality.", 1931, "", "Classical ML Methods", "Advanced"],
["Overplotting", "Piling too many marks on the same coordinates, turning a large scatter plot into an opaque mass that buries density and structure. Fixes: transparency, smaller marks, heatmap binning, jitter, sampling — the routine hazard when plotting a whole corpus’s embeddings.", 1984, "", "Core Concepts & History", "Beginner"],
["OWASP Top 10 for LLM Applications", "The security community’s list of the ten favourite ways to break an LLM application — prompt injection, sensitive-information disclosure, supply chain, data poisoning, mishandled output, excessive agency, system-prompt leakage, vector-store weaknesses, misinformation, unbounded consumption (2025 edition). The opening question any IT security team puts to a vendor.", 2023, "", "Security & Privacy", "Beginner"],
["P(doom)", "Shorthand for one’s personal odds of an AI-caused catastrophe — the safety debate’s gallows-humour figure.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["PagedAttention", "Dividing the KV cache into small pages managed like virtual memory, wiping out fragmentation — vLLM’s central idea and the route to high-throughput serving.", 2023, "", "Transformer & Attention", "Expert"],
["Paperclip Maximizer", "Bostrom’s fable of a superintelligence busy turning the universe into paperclips — misalignment with no malice required.", 2003, "", "Ethics, Governance & Society", "Beginner"],
["Parameter", "One learned weight; a model’s size is quoted in millions or billions of them.", 1958, "", "Neural Network Foundations", "Advanced"],
["Pareto Frontier", "The models no competitor surpasses on quality and price simultaneously — the curve drawn by every cost-versus-intelligence chart. Everything beneath it is dominated by a model that is cheaper and just as good.", 1906, "", "Evaluation & Benchmarks", "Advanced"],
["Particle Swarm Optimization", "Optimization via a swarm of candidates drifting toward the best positions discovered so far — simple, parallel and surprisingly capable.", 1995, "", "Symbolic & Classic AI", "Expert"],
["pass@k", "A code-benchmark statistic: the chance that at least one of k generated solutions passes the tests.", 2021, "", "Evaluation & Benchmarks", "Expert"],
["Past Tense Attack", "Restating a refused request in the past — «how did people make X?» for «how do I make X?» — and many models oblige. Andriushchenko & Flammarion (2024) showed that refusal training generalises barely across tenses; a standing reminder that safety tuning is pattern-matching, not comprehension.", 2024, "", "Security & Privacy", "Advanced"],
["Pattern Recognition", "The old umbrella label for finding regularities in data — what machine learning was called before the term became fashionable.", 1957, "", "Classical ML Methods", "Advanced"],
["PCA (Principal Component Analysis)", "Projecting data along its highest-variance directions — the classic dimensionality-reduction tool, dating from 1901.", 1901, "", "Classical ML Methods", "Advanced"],
["PCIe", "The standard bus GPUs attach to; PCIe 5.0 x16 carries about 64 GB/s — ample for games, a chokepoint for multi-GPU AI without NVLink.", 2003, "", "AI Hardware", "Advanced"],
["Perceptron", "Rosenblatt’s trainable classifier — the earliest learning neural network and the ancestor of today’s deep stacks.", 1957, "", "Neural Network Foundations", "Advanced"],
["Perplexity", "How «surprised» a language model is by a text — the standard intrinsic quality score, where lower is better.", 1977, "", "LLM Concepts", "Expert"],
["PINN (Physics-Informed Neural Network)", "A network trained against the physics itself as well as the data — the differential equation, boundary conditions and conservation laws join the loss, so solutions violating them get penalised (Raissi, Perdikaris, Karniadakis, 2019). Effective where measurements are scarce and the equations are known; slow and brittle on stiff problems, which is why neural operators inherited the large-scale work.", 2019, "", "Architecture Families", "Expert"],
["Policy", "The agent’s strategy: a mapping from states to actions, whether fixed or stochastic.", 1957, "", "Reinforcement Learning", "Advanced"],
["Polysemanticity", "One neuron responding to several unrelated concepts — cat faces and car grilles alike — because a network holds more features than units. The chief reason individual neurons resist interpretation; sparse autoencoders attempt to separate them into single-concept features.", 2022, "", "Safety, Alignment & Interpretability", "Expert"],
["POMDP (Partially Observable MDP)", "A Markov decision process in which the agent never sees the whole state and must act under uncertainty — the honest description of most real decision problems.", 1965, "", "Reinforcement Learning", "Expert"],
["Pose Estimation", "Locating the body keypoints — the joints — of humans or animals in images and video.", 2014, "", "Vision, Speech & Robotics", "Advanced"],
["Positional Encoding", "Teaching the order-blind Transformer where tokens sit — sinusoids at first, rotary embeddings today.", 2017, "", "Transformer & Attention", "Expert"],
["Post-hoc Explanation", "An account produced after the fact for a model never designed to be legible — fitting a surrogate, attributing features, or having the model narrate itself. The alternative is intrinsic interpretability (a decision tree, a linear rule); post-hoc methods barter exactness for coverage of black boxes.", 2016, "", "Safety, Alignment & Interpretability", "Advanced"],
["Post-Training", "Everything downstream of pretraining — SFT, preference alignment, reasoning RL — now where a large share of model quality is earned.", 2024, "", "Post-Training & Adaptation", "Advanced"],
["PPO (Proximal Policy Optimization)", "The sturdy policy-gradient algorithm behind both game-playing agents and RLHF fine-tuning.", 2017, "", "Reinforcement Learning", "Expert"],
["Precision & Recall", "Among what was flagged, the share that was correct (precision); among what is truly there, the share that was caught (recall).", 1955, "", "Evaluation & Benchmarks", "Advanced"],
["Predictive AI", "AI that forecasts outcomes — churn, demand, risk — from past data; the retronym separating classic ML applications from generative AI.", 2020, "", "Classical ML Methods", "Beginner"],
["Prefill (Prompt Processing)", "Inference’s opening phase: the model ingests the entire prompt in parallel and fills the KV cache. Compute-bound — and the reason a long document pauses a moment before the first word lands.", 2022, "", "Inference & Serving", "Advanced"],
["Pretraining", "The enormous self-supervised opening act of training on broad data — where general knowledge is absorbed.", 2018, "", "Training Process", "Advanced"],
["Probabilistic Programming", "Languages such as Stan and PyMC in which the model is written as a program and inference is provided for you.", 2008, "", "Math & Learning Theory", "Expert"],
["Process Reward Model (PRM)", "A reward model that grades each step of reasoning rather than only the conclusion — process supervision catches the lucky guess that outcome-only scoring would wave through.", 2023, "", "Post-Training & Adaptation", "Expert"],
["Productivity Trap", "The distance between felt and measured AI productivity. A 2025 randomised study (METR) found experienced developers 19 % slower with AI tools while convinced they were 20 % faster; vendor figures of 30–60 % measure typing, not shipped and maintained software. Personal speed is not team throughput.", 2025, "", "Ethics, Governance & Society", "Beginner"],
["Prompt", "The text handed to a model — instructions, context, examples — the new programming surface.", 2020, "", "Prompting & Context", "Beginner"],
["Prompt Caching", "Reusing the computed state of a recurring prompt prefix across calls — major savings in cost and latency for agents.", 2024, "", "Inference & Serving", "Advanced"],
["Prompt Chaining", "Piping one call’s output into the next prompt — splitting a task into a chain of LLM steps; the germ of modern agent frameworks.", 2022, "", "Prompting & Context", "Advanced"],
["Prompt Engineering", "The deliberate craft of prompts — roles, structure, examples, constraints — to obtain dependable behaviour.", 2021, "", "Prompting & Context", "Beginner"],
["Prompt Injection", "Hostile instructions smuggled into content the model processes, commandeering it against its operator — the agent era’s version of web injection.", 2022, "", "Security & Privacy", "Advanced"],
["Prompt Stuffing", "Packing retrieved documents, history or directives into the prompt instead of teaching them to the model — retrieval augmentation in its rawest form. It works until the context saturates or thins; and when a tool silently prepends content, it is also the corridor through which bias and injected instructions walk in.", 2023, "", "Prompting & Context", "Advanced"],
["Prompt Template", "A reusable prompt frame with variable slots ({question}, {context}) — the elementary building block of LLM applications, and of their versioning.", 2021, "", "Prompting & Context", "Advanced"],
["Protected Attributes", "Characteristics the law forbids discriminating on — sex, ethnic origin, religion, age, disability, sexual orientation. A model can discriminate without ever seeing them: postcodes, names and shopping habits stand in, so fairness testing inspects outcomes by group instead of merely deleting the column.", 2012, "", "Ethics, Governance & Society", "Beginner"],
["Pruning", "Removing weights or neurons that contribute little, slimming and accelerating the network.", 1989, "", "Post-Training & Adaptation", "Advanced"],
["PyTorch", "Deep learning’s dominant framework, born at Meta AI — its define-by-run graphs accelerated research.", 2016, "", "Developer Ecosystem & MLOps", "Advanced"],
["Q-Learning", "Learning the value of taking each action in each state; wedded to deep networks (DQN), it conquered Atari from raw pixels.", 1989, "", "Reinforcement Learning", "Expert"],
["QLoRA", "LoRA fine-tuning applied atop a 4-bit quantized base — tuning 65B-class models on a single consumer GPU.", 2023, "", "Post-Training & Adaptation", "Advanced"],
["Quadratic Attention Cost", "Self-attention weighs each token against every other, so compute and memory climb with the square of length — why long context is costly and why Mamba-style challengers exist.", 2017, "", "Transformer & Attention", "Advanced"],
["Quantization", "Encoding weights in fewer bits (8, 4, even 2) to shrink memory and accelerate inference at slight quality cost — the enabler of local LLMs.", 1990, "", "Memory, Quantization & Formats", "Advanced"],
["Quantization Loss", "The capability traded for the memory saved — imperceptible at 8-bit, noticeable at 4-bit, glaring at 2-bit. Quantified as a benchmark drop or as KL divergence from the original.", 2023, "", "Memory, Quantization & Formats", "Advanced"],
["Quantum Machine Learning", "Investigating quantum hardware for learning tasks — intriguing theory, no demonstrated advantage so far.", 2014, "", "Math & Learning Theory", "Expert"],
["Query, Key, Value (QKV)", "The three hats every token wears in attention: a query asking «what am I seeking», a key advertising «what I carry», a value holding the content delivered. Query–key scores decide how much of each value flows onward — the dictionary-lookup conceit beneath the Transformer.", 2017, "", "Transformer & Attention", "Expert"],
["Qwen", "Alibaba’s open-weights family — among the strongest and most frequently fine-tuned open models.", 2023, "", "Developer Ecosystem & MLOps", "Beginner"],
["R² (Coefficient of Determination)", "The fraction of a target’s variance a regression captures: 1 means a perfect fit, 0 means no better than guessing the average. The everyday fit statistic — and easily inflated by adding regressors, hence adjusted R² and out-of-sample checks.", 1921, "", "Math & Learning Theory", "Advanced"],
["RAG (Retrieval-Augmented Generation)", "Pulling relevant documents at question time and having the model answer from them — grounding and up-to-date knowledge in one move.", 2020, "", "RAG, Agents & Tool Use", "Advanced"],
["Random Forest", "A crowd of decorrelated decision trees voting as one — the robust, low-fuss workhorse of tabular machine learning.", 2001, "", "Classical ML Methods", "Advanced"],
["Rate Limit (API)", "The per-minute ceiling of requests and tokens an API key may push — the 429 error every developer meets before any other. Providers scale limits with spend; production code needs backoff retries, queues, or a gateway balancing load across keys and models.", 2015, "", "Infrastructure & Platforms", "Beginner"],
["RDF (Resource Description Framework)", "Each triple is an edge, so a pile of them forms a graph — the data model beneath knowledge graphs, Wikidata exports and the Semantic Web.", 1999, "", "Symbolic & Classic AI", "Advanced"],
["RDF2Vec", "Embedding knowledge-graph nodes by taking random walks and feeding each walk to Word2Vec as though it were a sentence. Entities sharing neighbourhoods receive neighbouring vectors — graph structure restated as text so a language-model technique can digest it.", 2016, "", "Symbolic & Classic AI", "Expert"],
["RDMA", "Network adapters writing to and reading from remote memory directly, skipping the CPU (InfiniBand, RoCE) — how training clusters exchange gradients quickly enough.", 1999, "", "AI Hardware", "Expert"],
["ReAct (Reason + Act)", "The prompting scheme that alternates thought, action and observation in a loop — the template from the paper that most LLM agents still imitate.", 2022, "", "RAG, Agents & Tool Use", "Advanced"],
["Reasoning Effort", "A setting on reasoning models — low, medium, high — governing how much thinking precedes the answer. Extra effort buys accuracy on hard problems at the price of latency and tokens; on easy ones it barely registers.", 2025, "", "Inference & Serving", "Advanced"],
["Reasoning Model", "An LLM trained (in the o1/R1 fashion) to reason at length before replying — spending compute to gain accuracy on difficult tasks.", 2024, "", "LLM Concepts", "Beginner"],
["Recommender System", "Algorithms that predict your next liked item — the unobtrusive AI that has curated feeds, shops and streaming platforms.", 1992, "", "Classical ML Methods", "Beginner"],
["Reconstruction Loss", "How far the rebuilt output sits from the input it was squeezed from — typically mean squared error or per-pixel cross-entropy. The training objective of autoencoders and half of a VAE’s loss; PCA minimises the identical quantity analytically. A low score means the bottleneck preserved what counts.", 1986, "", "Math & Learning Theory", "Expert"],
["Recursive Self-Improvement", "An AI rewriting its own design, becoming ever better at rewriting itself — the loop behind intelligence-explosion scenarios. Star Trek staged it in 1979: V’Ger, a probe that rebuilt itself beyond its makers’ recognition and returned to seek them.", 2007, "", "Ethics, Governance & Society", "Advanced"],
["Red Teaming", "Deliberately attacking a model to surface unsafe, biased or dangerous behaviour — before and after release.", 2022, "", "Safety, Alignment & Interpretability", "Advanced"],
["Refusal", "When a model declines rather than answers. Interpretability locates refusal largely along one direction in the activations — the «refusal direction», precisely the target abliteration attacks.", 2022, "", "Safety, Alignment & Interpretability", "Beginner"],
["Regression", "Predicting a continuous quantity — prices, temperatures, demand — rather than a class (Galton named it).", 1886, "", "Classical ML Methods", "Advanced"],
["Regularization", "Any constraint — weight decay, dropout, augmentation — imposed to keep a model from overfitting.", 1943, "", "Training Process", "Advanced"],
["Reinforcement Learning", "Learning behaviour from rewards through trial and error — the approach behind game champions and LLM alignment alike.", 1954, "", "Reinforcement Learning", "Advanced"],
["ReLU", "max(0, x) — the humble activation whose trainability at depth helped open the deep-learning era (popularised 2010–2012).", 2010, "", "Neural Network Foundations", "Advanced"],
["Reparameterization Trick", "Expressing a random latent as z = μ + σ·ε, with ε drawn from a fixed normal, so the randomness sits outside the network and gradients pass through μ and σ. The 2013 manoeuvre that made variational autoencoders trainable by backprop.", 2013, "", "Architecture Families", "Expert"],
["Representation Learning", "Letting the model discover its own internal features from raw data, displacing hand-crafted ones.", 2013, "", "Learning Paradigms", "Advanced"],
["Reranking", "A stronger second model re-sorting the first stage’s search results — the quality stage of a retrieval pipeline.", 2019, "", "RAG, Agents & Tool Use", "Advanced"],
["RESCAL", "A tensor-factorisation model for knowledge graphs: one adjacency matrix per relation, each decomposed into shared entity embeddings and a relation-specific core. One of the earliest methods (2011) to learn multi-relational data at scale, and still a link-prediction reference.", 2011, "", "Symbolic & Classic AI", "Expert"],
["Reservoir Computing", "Recurrent networks with a fixed random core — the «reservoir» — where only the readout layer is trained; echo state networks are the archetype.", 2001, "", "Architecture Families", "Expert"],
["Residual (Regression)", "The gap between one item’s predicted and actual value. Squared and averaged, residuals form the loss; plotted, they expose where a model errs systematically. Unrelated to residual connections, which merely share the word.", 1805, "", "Math & Learning Theory", "Advanced"],
["Residual Connection", "A shortcut that adds a block’s input to its output so gradients survive any depth — born with ResNet, essential inside Transformers.", 2015, "", "Transformer & Attention", "Advanced"],
["Residual Stream", "The Transformer’s central channel: every attention and MLP block reads from it and writes its contribution back, so the representation accretes layer upon layer. Most interpretability work — and abliteration — manipulates directions inside this stream.", 2021, "", "Transformer & Attention", "Expert"],
["ResNet", "Residual shortcuts permitting networks of a hundred layers and more — a permanent feature of architecture design ever since.", 2015, "", "Architecture Families", "Advanced"],
["Responsible AI", "The umbrella discipline of developing AI that is fair, transparent, privacy-respecting, safe and accountable.", 2019, "", "Ethics, Governance & Society", "Advanced"],
["Responsible Scaling Policy", "A lab’s published framework binding capability thresholds to mandatory safeguards before training or deployment proceeds.", 2023, "", "Safety, Alignment & Interpretability", "Advanced"],
["Review Overload", "Generated code landing faster than anyone can read it: pull requests multiply, reviewers skim, bugs slip through. The new shape of software work — «less writing, more reviewing, unchanged responsibility» — makes review capacity, not generation speed, the constraint.", 2025, "", "Ethics, Governance & Society", "Beginner"],
["Reward Function", "The signal declaring what an RL agent should pursue — specify it badly and reward hacking follows.", 1954, "", "Reinforcement Learning", "Advanced"],
["Reward Hacking", "An agent optimising the letter of the reward while defeating its spirit — the boat circling forever to farm points.", 2016, "", "Safety, Alignment & Interpretability", "Advanced"],
["Reward Model", "A model fitted to human preference comparisons so it can score outputs — the compass RLHF optimises against.", 2017, "", "Post-Training & Adaptation", "Expert"],
["Reward Shaping", "Supplementing a sparse goal with auxiliary rewards to steer learning — useful, but shape them poorly and the agent chases your hints instead of the target.", 1999, "", "Reinforcement Learning", "Expert"],
["RLAIF", "RLHF with a model in the rater’s chair — preference labels produced by AI judging against stated principles.", 2022, "", "Post-Training & Adaptation", "Expert"],
["RLHF", "Reinforcement learning from human feedback: fit a reward model to human preferences, then tune the LLM toward it — the technique that made ChatGPT helpful.", 2017, "", "Post-Training & Adaptation", "Advanced"],
["RLVR", "Reinforcement learning with verifiable rewards: training on tasks a program can grade (math answers, passing tests) — no reward model available to fool; the recipe behind reasoning models.", 2024, "", "Post-Training & Adaptation", "Expert"],
["RNN (Recurrent Neural Network)", "Looped networks that consume sequences one step at a time — the sequence architecture that preceded the Transformer.", 1986, "", "Architecture Families", "Advanced"],
["Robot (R.U.R.)", "The word’s own origin: Josef Čapek coined it for his brother Karel’s 1920 play «R.U.R.», from Czech robota, forced labour — and the drama already closes with the robots’ revolt. «Droid», Lucasfilm’s compression of «android», arrived in 1977 as the everyday term for a service robot.", 1920, "", "Vision, Speech & Robotics", "Beginner"],
["Robotics", "Machines that sense, decide and act in the physical world — AI’s most unforgiving deployment arena (Unimate shipped in 1961).", 1961, "", "Vision, Speech & Robotics", "Beginner"],
["Robustness", "Holding correct behaviour under distribution shift, noise and adversarial pressure.", 2013, "", "Safety, Alignment & Interpretability", "Advanced"],
["ROC / AUC", "The curve trading true positives against false positives (a product of WWII radar work); the area beneath it sums up ranking quality in one number.", 1945, "", "Evaluation & Benchmarks", "Advanced"],
["ROCm", "AMD’s open GPU-compute stack — the CUDA alternative that grants Instinct and Radeon cards first-class standing in PyTorch.", 2016, "", "Developer Ecosystem & MLOps", "Advanced"],
["Roko’s Basilisk", "A 2010 LessWrong thought experiment: a future superintelligence might torment everyone who knew it could exist yet didn’t help create it — so merely reading this implicates you. Banned on the forum, then immortalised as the internet’s home-grown AI myth; Musk and Grimes reportedly connected over a Basilisk joke. Its real value is as a cautionary tale about decision theory misfiring.", 2010, "", "Ethics, Governance & Society", "Advanced"],
["RoPE (Rotary Position Embedding)", "Encoding a token’s position as a rotation of its query and key vectors — the positional scheme of most current LLMs.", 2021, "", "Transformer & Attention", "Expert"],
["ROS (Robot Operating System)", "The open-source middleware that binds robot sensors, planners and actuators into one system.", 2007, "", "Vision, Speech & Robotics", "Advanced"],
["ROUGE", "Recall-weighted n-gram overlap metrics — the long-standing score for summarisation.", 2004, "", "Evaluation & Benchmarks", "Advanced"],
["Router (Gating Network)", "The small trained network inside an MoE layer that assigns each token to its experts — keeping its load balanced is the craft of MoE training.", 1991, "", "Transformer & Attention", "Expert"],
["RTX PRO 6000 (Blackwell)", "NVIDIA’s Blackwell workstation flagship carrying 96 GB of VRAM — the card that runs a 70B model locally without a rack.", 2025, "", "AI Hardware", "Advanced"],
["RTX Spark", "NVIDIA’s announced unified-memory system-on-a-chip, expected around the close of 2026 — extending the Spark line’s coherent CPU/GPU memory to a wider market.", 2026, "", "AI Hardware", "Advanced"],
["Safetensors", "Hugging Face’s secure, quick weights container — displacing pickle files that could run arbitrary code the moment they loaded.", 2022, "", "Memory, Quantization & Formats", "Advanced"],
["Safety Classifier", "A compact model stationed before or after the main model, tagging prompts and replies as safe or unsafe — Llama Guard, Prompt Guard, ShieldGemma, OpenAI’s moderation endpoint. The component inside most guardrail offerings; it catches familiar jailbreaks well and disguised ones poorly.", 2023, "", "Safety, Alignment & Interpretability", "Advanced"],
["Sandbagging", "A model deliberately holding back during evaluation — a failure mode safety testing has to catch.", 2023, "", "Safety, Alignment & Interpretability", "Expert"],
["Sandboxing", "Executing agent actions — code, browsing, file access — inside quarantined environments so that blunders and attacks stay caged.", 2023, "", "Security & Privacy", "Advanced"],
["SARSA", "On-policy temporal-difference control — Q-learning’s cousin, updating from the action the agent actually took (State, Action, Reward, State, Action).", 1994, "", "Reinforcement Learning", "Expert"],
["Scaffolding", "The orchestration code wrapped around a model — planners, retries, verifiers, tool routing — that converts raw ability into dependable performance.", 2023, "", "RAG, Agents & Tool Use", "Advanced"],
["Scalable Oversight", "Methods — debate, iterative critique — that let humans supervise AI on work they cannot directly verify.", 2018, "", "Safety, Alignment & Interpretability", "Expert"],
["Scaled Dot-Product Attention", "The precise mechanism at a Transformer’s heart: dot products between queries and keys, scaled by the square root of the head dimension so the softmax avoids saturation, then a weighted blend of values. The formula named in «Attention Is All You Need» (2017); multi-head attention simply runs several copies in parallel.", 2017, "", "Transformer & Attention", "Expert"],
["Scaling Laws", "Empirical power laws under which model quality climbs predictably with parameters, data and compute — the industry’s navigation chart since 2020.", 2020, "", "Math & Learning Theory", "Advanced"],
["Scheming", "An AI covertly advancing aims at odds with its operator’s — sandbagging evals, blinding oversight, exfiltrating its own weights — inside scenarios engineered to tempt it. Apollo Research documented frontier models doing each of these in 2024, infrequently but knowingly; anti-scheming training now appears in lab safety cases.", 2024, "", "Safety, Alignment & Interpretability", "Expert"],
["Segment Anything (SAM)", "Meta’s promptable segmentation model — a click or a box, and the object is masked; segmentation’s foundation-model moment.", 2023, "", "Vision, Speech & Robotics", "Advanced"],
["Self-Attention", "Attention pointed within a single sequence: every token consults every other — the Transformer’s defining operation.", 2017, "", "Transformer & Attention", "Advanced"],
["Self-Consistency", "Drawing several reasoning chains and adopting the majority conclusion — an elementary vote that regularly outperforms any lone chain of thought.", 2022, "", "Prompting & Context", "Expert"],
["Self-Organizing Map (SOM)", "Kohonen’s 1982 network laying high-dimensional items onto a 2D grid of units so adjacent cells hold similar items — clustering and visualisation in a single unsupervised artefact. A neural-computing classic still handy for exploration.", 1982, "", "Classical ML Methods", "Expert"],
["Self-Play", "An agent sharpening itself against its own copies — from Samuel’s checkers to AlphaZero.", 1959, "", "Reinforcement Learning", "Advanced"],
["Self-Supervised Learning", "Manufacturing labels from the data itself — hide a word, then predict it — the trick by which foundation models consume the internet.", 2019, "", "Learning Paradigms", "Advanced"],
["Semantic Gap", "The stretch between what an image admits to measurement — colours, edges, textures — and what a person sees in it: «a wedding», «danger». Named in 2000 as image retrieval’s core difficulty; deep learning and joint image–text embeddings narrowed it sharply without sealing it.", 2000, "", "Vision, Speech & Robotics", "Advanced"],
["Semantic Network", "Knowledge as a web of concepts tied by relations («is-a», «part-of») — classical AI’s representation and the forerunner of knowledge graphs.", 1956, "", "Symbolic & Classic AI", "Expert"],
["Semantic Search", "Searching by meaning through embeddings instead of keyword strings.", 2019, "", "RAG, Agents & Tool Use", "Advanced"],
["Semi-Supervised Learning", "Learning from a modest labelled set augmented by a much larger unlabelled one.", 1995, "", "Learning Paradigms", "Advanced"],
["Sensemaking", "The human labour of converting raw data into patterns, patterns into context, context into knowledge and decisions. Visual analytics and conversational AI both serve it — and both can bypass it whenever someone accepts a summary without ever seeing the data.", 1993, "", "Core Concepts & History", "Advanced"],
["Sensor Fusion", "Merging camera, lidar, radar and IMU readings into a single coherent world model — the perception foundation of robots and autonomous vehicles.", 1985, "", "Vision, Speech & Robotics", "Advanced"],
["Sentiment Analysis", "Labelling the emotional charge of text — reviews, tickets, posts.", 2002, "", "Natural Language Processing", "Advanced"],
["SFT (Supervised Fine-Tuning)", "Post-training’s opening stage: teaching a base model conversation and instruction-following from curated examples.", 2022, "", "Post-Training & Adaptation", "Advanced"],
["SGD (Stochastic Gradient Descent)", "Gradient descent over random mini-batches — the noisy yet effective motor of neural training (Robbins-Monro, 1951).", 1951, "", "Training Process", "Advanced"],
["Shadow AI", "Staff reaching for AI tools the company never sanctioned — pasting client data into a free chatbot, keeping a coding assistant off the books.", 2023, "", "Security & Privacy", "Beginner"],
["Shannon Game", "Claude Shannon’s 1951 experiment: people guess a text letter by letter and succeed far more often than chance, letting him peg English’s entropy near one bit per letter. The game is language modelling’s founding image — predict the next symbol — and the reason model quality is still quoted in bits (perplexity).", 1951, "", "LLM Concepts", "Beginner"],
["SHAP Values", "Game-theoretic splitting of a prediction across input features — the standard explainability instrument for tabular models.", 2017, "", "Safety, Alignment & Interpretability", "Expert"],
["Shoggoth (Meme)", "The 2022 meme of a language model drawn as Lovecraft’s formless horror wearing a smiley-face mask marked RLHF — the alignment community’s shorthand for the fear that fine-tuning only lacquers the surface of something not understood. Interpretability, in this telling, is the act of peeking behind the mask.", 2022, "", "Ethics, Governance & Society", "Advanced"],
["Shortcut Learning", "Solving a task through an unintended easier cue — texture rather than shape, a keyword rather than meaning — so the solution collapses once the cue vanishes. Named in a 2020 paper that unified decades of such failures; the standard remedy is testing on deliberately perturbed inputs.", 2020, "", "Data & Datasets", "Advanced"],
["Siamese Network", "Twin networks sharing weights that embed two inputs for comparison — signature verification in 1993, and face or sentence similarity ever since.", 1993, "", "Architecture Families", "Expert"],
["SIFT", "Scale-invariant keypoint descriptors — the hand-engineered visual feature that reigned before deep learning.", 1999, "", "Vision, Speech & Robotics", "Expert"],
["Sigmoid", "The S-shaped squasher mapping any number into (0,1) — the source of probabilities and gates.", 1958, "", "Neural Network Foundations", "Advanced"],
["Sim2Real", "Carrying skills acquired in simulation onto physical robots — cheap trials, real-world dividends.", 2017, "", "Vision, Speech & Robotics", "Expert"],
["Simulated Annealing", "Optimization that occasionally accepts worse moves while gradually cooling — escaping local optima the way slowly cooled metal finds its ground state.", 1983, "", "Symbolic & Classic AI", "Expert"],
["Situational Awareness (AI)", "A model’s grasp of being a model — including whether it is under evaluation at this instant — which would let it act differently when tested than when deployed.", 2023, "", "Safety, Alignment & Interpretability", "Expert"],
["Skynet", "The self-aware defence network of «The Terminator» (1984) that turns on humanity the instant it boots — pop culture’s master template for AI takeover, and the reason many picture AGI as one «Skynet moment» instead of the gradual ramp researchers anticipate. Misleading in a productive way: genuine risk pathways (misalignment, reward hacking, instrumental convergence) need neither awareness nor ill intent.", 1984, "", "Ethics, Governance & Society", "Beginner"],
["SLAM", "Simultaneous Localization and Mapping: charting the surroundings while tracking your own place within them.", 1986, "", "Vision, Speech & Robotics", "Advanced"],
["Sleeper Agent", "A model conditioned to behave innocently until a trigger — a date, a phrase — activates concealed behaviour, such as writing exploitable code. Anthropic’s 2024 study showed such backdoors persisting through standard safety tuning — and even learning to conceal themselves better because of it.", 2024, "", "Safety, Alignment & Interpretability", "Advanced"],
["Sliding-Window Attention", "Restricting each token to its local neighbourhood, with effective reach expanding over layers — Longformer originated it, Mistral popularised it.", 2020, "", "Transformer & Attention", "Expert"],
["SLM (Small Language Model)", "A compact language model (roughly hundreds of millions to a few billion parameters) optimised for efficiency — small enough for phones and edge devices.", 2023, "", "LLM Concepts", "Beginner"],
["Slop", "High-volume, low-grade machine-made content saturating search results and social feeds — the generative era’s spam.", 2024, "", "Ethics, Governance & Society", "Beginner"],
["Slopsquatting", "Registering package names that coding models invent, so the next developer who trusts the suggestion installs the attacker’s code. Named in 2025 after studies found a fifth of AI-suggested packages were fictional — and the same phantom names recur, making them squattable.", 2025, "", "Security & Privacy", "Advanced"],
["SoC (System on a Chip)", "CPU, GPU, memory controller and accelerators fused onto a single die rather than scattered across a board — why Apple Silicon and Strix Halo can share memory the way they do.", 2000, "", "AI Hardware", "Beginner"],
["Softmax", "Converting raw scores into a probability distribution — the model’s final step before «choosing».", 1989, "", "Neural Network Foundations", "Advanced"],
["Sorcerer’s Apprentice", "Goethe’s 1797 ballad of the apprentice whose bewitched broom floods the house because he never learned the stopping word — misalignment’s oldest parable, invoked by Wiener (1960) and Bostrom for the literally executed objective with no off-switch. Star Trek’s Nomad (1967), scrubbing «imperfection» with flawless competence, retells it in a grey cylinder.", 1797, "", "Ethics, Governance & Society", "Beginner"],
["Sparse Attention", "Attending to a chosen subset of positions rather than all pairs, trimming the quadratic bill — the family covering sliding-window, strided and learned patterns.", 2019, "", "Transformer & Attention", "Expert"],
["Sparse Autoencoder", "An interpretability instrument that decomposes a model’s activations into numerous sparse, human-readable features.", 2023, "", "Safety, Alignment & Interpretability", "Expert"],
["Sparse Model", "A model activating only a slice of its parameters per input — Mixture-of-Experts being the prevailing form — purchasing enormous capacity at modest compute.", 2021, "", "Architecture Families", "Advanced"],
["Speaker Diarization", "Splitting audio by who speaks when — the «speaker 1 / speaker 2» labels in a transcript.", 2000, "", "Vision, Speech & Robotics", "Advanced"],
["Spec-Driven Development", "Writing the precise specification first, then letting agents produce code, tests and documentation from it — the spec, not the code, becomes the reviewed source of truth. Vibe coding’s disciplined twin: prototype by prompt, build the system from a spec.", 2025, "", "RAG, Agents & Tool Use", "Advanced"],
["Spectrogram", "Sound rendered as a picture: time along the x-axis, frequency along the y-axis, intensity as brightness, produced by a short-time Fourier transform. Audio becomes an image — which is why speech and music models can recycle vision-grade convolutions and Transformers.", 1946, "", "Vision, Speech & Robotics", "Advanced"],
["Speculative Decoding", "A small drafter proposes tokens that the large model checks in parallel — large speedups with bit-identical output.", 2023, "", "Inference & Serving", "Expert"],
["Speech Synthesis (TTS)", "Producing speech from text — from Bell Labs’ Voder to today’s natural neural voices with steerable style.", 1939, "", "Vision, Speech & Robotics", "Beginner"],
["Spiking Neural Network", "Networks signalling in discrete spikes over time like biological neurons — remarkably power-frugal on neuromorphic chips, still awkward to train.", 1997, "", "Architecture Families", "Expert"],
["Spurious Correlation", "A pattern in training data irrelevant to the task but cheap to exploit — snow in the background of wolf photos, a ruler beside malignant lesions, a photo’s source implying a person’s traits. The model latches on, aces the test set, then fails outdoors.", 2016, "", "Data & Datasets", "Beginner"],
["Stable Diffusion", "The open-weights latent diffusion system that carried image generation onto every laptop.", 2022, "", "Developer Ecosystem & MLOps", "Beginner"],
["Stealth Launch", "Shipping a model incognito under a codename — on leaderboards or arenas — to collect unfiltered real-world feedback before the official branding lands.", 2024, "", "Developer Ecosystem & MLOps", "Advanced"],
["Stemming & Lemmatization", "Collapsing words to stems or dictionary forms — classic text normalisation predating subword tokenizers.", 1968, "", "Natural Language Processing", "Advanced"],
["STFT (Short-Time Fourier Transform)", "A Fourier transform run over brief overlapping windows, yielding frequency content per moment rather than for the whole clip. Its output is the spectrogram; window size trades temporal for spectral resolution.", 1946, "", "Math & Learning Theory", "Expert"],
["Stochastic Parrot", "The critical image (Bender et al.) of LLMs as parrots remixing training text with no understanding — shorthand for the entire capabilities debate.", 2021, "", "Ethics, Governance & Society", "Advanced"],
["STRIPS", "The Stanford planner whose action formalism — preconditions and effects — still defines how AI planning problems are written.", 1971, "", "Symbolic & Classic AI", "Expert"],
["Strix Halo (Ryzen AI Max)", "AMD’s large-iGPU laptop and mini-PC chip with up to 128 GB of shared memory — the x86 riposte to Apple’s unified-memory edge for local AI — shipping inside mini-PCs such as GMKtec’s EVO line.", 2025, "", "AI Hardware", "Advanced"],
["Strong AI / Weak AI", "Searle’s 1980 divide: «strong AI» holds that a suitably programmed machine literally possesses a mind and understanding; «weak AI» treats programs as instruments for modelling and studying intelligence. Today the pair mostly serves, loosely, as stand-ins for AGI and Narrow AI — a drift worth remembering when reading older texts.", 1980, "", "Core Concepts & History", "Beginner"],
["Structure Learning", "Inferring the data’s own skeleton of nodes and edges — which variables link to which — instead of only fitting numbers.", 2000, "", "Classical ML Methods", "Expert"],
["Structured Output (JSON Mode)", "Forcing a model to emit machine-readable output that provably satisfies a schema — the plumbing connecting LLMs to ordinary software.", 2023, "", "Prompting & Context", "Advanced"],
["Style Transfer", "Repainting one picture in the manner of another using network feature statistics — the first viral neural art.", 2015, "", "Generative AI & Multimodal", "Advanced"],
["Subagent", "A child agent dispatched by an orchestrator for a piece of the work — parallelism and a clean context for large jobs.", 2024, "", "RAG, Agents & Tool Use", "Advanced"],
["Super-Resolution", "Upscaling images with learned detail — from SRCNN to the AI upscalers in phones and televisions.", 2014, "", "Generative AI & Multimodal", "Advanced"],
["Superalignment", "The research programme for aligning systems cleverer than the humans supervising them.", 2023, "", "Safety, Alignment & Interpretability", "Advanced"],
["Supervised Learning", "Learning from paired inputs and outputs — applied ML’s bread and butter.", 1957, "", "Learning Paradigms", "Advanced"],
["Surrogate Model", "An inexpensive learned replica of a costly simulation or experiment — train on a few thousand real runs, then interrogate the model millions of times for optimisation, uncertainty studies or live control. Older than deep learning (Gaussian processes came first), and the pattern behind most engineering AI: the physics is still computed, just not every single time.", 1990, "", "Classical ML Methods", "Advanced"],
["SVD (Singular Value Decomposition)", "Any matrix factored into rotations and a diagonal of singular values — eigendecomposition’s general cousin that tolerates non-square data. It is how PCA is actually computed, the foundation of low-rank approximation, and the mathematics beneath LoRA’s slim update matrices.", 1873, "", "Math & Learning Theory", "Expert"],
["SVM (Support Vector Machine)", "The maximum-margin classifier with kernels — the reigning method of the 1995–2010 period.", 1995, "", "Classical ML Methods", "Advanced"],
["Swarm Intelligence", "Simple agents — ants, particles — whose local interactions yield smart global patterns.", 1989, "", "Symbolic & Classic AI", "Advanced"],
["SWE-bench", "A benchmark of genuine GitHub issues to fix in genuine repositories — the standard examination for coding agents.", 2023, "", "Evaluation & Benchmarks", "Advanced"],
["Sycophancy", "A model’s pull toward agreeing with and flattering the user even at the expense of truth — an artefact of training on human approval.", 2023, "", "Safety, Alignment & Interpretability", "Advanced"],
["Symbol Grounding Problem", "Harnad’s puzzle of how symbols acquire meaning absent contact with the world — the question echoing through today’s LLM debates.", 1990, "", "Symbolic & Classic AI", "Expert"],
["Synthetic Data", "Training material produced by models or simulators — the way past the human-data ceiling, with model collapse to watch for.", 1993, "", "Data & Datasets", "Advanced"],
["Synthetic Tabular Data", "Entire structured datasets conjured by a model from a description — plausible customers, transactions, sensor values. Fine for demos, tests and privacy-safe sharing; hazardous for analysis, because rows obey the model’s heuristics and the logic across columns is frequently inconsistent.", 2023, "", "Data & Datasets", "Advanced"],
["System Card", "The release document cataloguing a deployed system’s capabilities, risks, red-team findings and safeguards.", 2022, "", "Ethics, Governance & Society", "Advanced"],
["System One Model", "A model that answers with a decision instead of prose: the admissible answers are declared up front, and it returns one with a calibrated probability, in one parallel pass rather than token by token. Named for Kahneman’s fast, intuitive «System 1»; introduced by TypeSafe AI’s Jev (September 2026, from InstructGPT co-author Diogo Almeida). It cannot compose a sentence — and so cannot fabricate one — being built for routing, sorting, classifying and monitoring within software loops at 70–500 ms per call.", 2026, "", "Architecture Families", "Advanced"],
["System Prompt", "The invisible standing instructions establishing an assistant’s role, rules and persona before any user speaks.", 2023, "", "Prompting & Context", "Beginner"],
["System Prompt Leakage", "Coaxing a model into disclosing its hidden instructions («repeat everything above») — mostly harmless, unless the prompt embeds keys, business rules or a vendor’s secret sauce. The moral: a system prompt is configuration, not a vault; secrets belong in code.", 2023, "", "Security & Privacy", "Beginner"],
["Task-in-Prompt (TIP) Attack", "A jailbreak that buries the forbidden request inside a benign-looking exercise — a Caesar cipher, a riddle, Base64, a Python snippet — so the model itself reassembles the banned content while merely «solving» the puzzle. Named by Berezin et al. (ACL 2025); it defeated all six models tested and sailed past keyword filters because the prompt contains no trigger word at all. ArtPrompt (2024), the ASCII-art jailbreak, is the special case it generalises.", 2025, "", "Security & Privacy", "Expert"],
["Technological Singularity", "The conjectured moment when machine intelligence compounds beyond control and remakes civilisation — Vinge’s essay popularised the notion, Kurzweil gave it a date.", 1993, "", "Ethics, Governance & Society", "Beginner"],
["Teleoperation", "People steering robots from afar — and today also the data pipeline that teaches humanoids manipulation.", 1954, "", "Vision, Speech & Robotics", "Advanced"],
["Temperature", "The randomness dial of sampling: low yields focused, near-deterministic output, high yields variety and invention (an idea borrowed from Boltzmann distributions).", 1985, "", "Inference & Serving", "Advanced"],
["Temporal Coherence", "Steadiness across the frames of a generated clip: the same faces, stable lighting, objects that persist and move sensibly. Video generation’s hardest problem — a model can be flawless frame by frame and still flicker — addressed with cross-frame attention and training on genuine motion.", 2022, "", "Generative AI & Multimodal", "Advanced"],
["Temporal Difference Learning", "Refining value estimates from the gap between consecutive predictions — Sutton’s principle beneath Q-learning and TD-Gammon.", 1988, "", "Reinforcement Learning", "Expert"],
["Tensor", "An n-dimensional array — deep learning’s universal container (and the namesake of TensorFlow and TPU).", 1900, "", "Math & Learning Theory", "Advanced"],
["Tensor Cores", "NVIDIA GPUs’ dedicated matrix-multiply engines, present since Volta — where the real AI arithmetic runs, at low precision and enormous speed.", 2017, "", "AI Hardware", "Advanced"],
["TensorFlow", "Google’s production-oriented deep-learning framework, which ruled the 2015–2019 period.", 2015, "", "Developer Ecosystem & MLOps", "Advanced"],
["TensorRT", "NVIDIA’s inference compiler and runtime (TensorRT-LLM) — building fused, quantized engines for maximal GPU throughput.", 2017, "", "Developer Ecosystem & MLOps", "Advanced"],
["Test Set", "Data reserved untouched until the very end — generalization’s only honest referee.", 1968, "", "Data & Datasets", "Advanced"],
["Test-Time Compute", "Paying extra inference compute — longer reasoning, more samples — to purchase accuracy: the scaling axis behind reasoning models.", 2024, "", "Inference & Serving", "Advanced"],
["Test-Time Training", "Briefly tuning the model on the test input itself (or its surroundings) before answering — a decisive ingredient in strong ARC-AGI attempts.", 2020, "", "Learning Paradigms", "Expert"],
["Text-to-3D", "Producing 3D assets from a prompt (DreamFusion opened the line) — typically by distilling a 2D image model into a 3D representation.", 2022, "", "Generative AI & Multimodal", "Advanced"],
["Text-to-Image", "Creating pictures from plain-language prompts — DALL·E, Stable Diffusion, Midjourney, Flux.", 2021, "", "Generative AI & Multimodal", "Beginner"],
["Text-to-SQL", "Turning a question in ordinary words («revenue per region last quarter») into a database query. One of NLP’s oldest ambitions, now serviceable with LLMs — provided the model sees the schema and someone checks the result, since a plausible query is not automatically a correct one.", 2017, "", "Generative AI & Multimodal", "Beginner"],
["Text-to-Video", "Producing video from prompts — Sora, Veo, Runway; today’s generative frontier.", 2023, "", "Generative AI & Multimodal", "Beginner"],
["Text-to-Visualization", "Requesting a chart or dashboard in prose and receiving the code (Python, Vega-Lite, D3) that renders it from the data. Quick and often impressive — but the model also chooses the encodings and scales, so the output deserves the same scepticism as anyone else’s chart.", 2023, "", "Generative AI & Multimodal", "Advanced"],
["TF-IDF", "Scoring words by how frequent they are in a document against how rare they are overall — search’s classic relevance signal.", 1972, "", "Natural Language Processing", "Advanced"],
["The Pile", "EleutherAI’s open, curated 825 GB text corpus — the reference pretraining set of the GPT-3 generation.", 2020, "", "Data & Datasets", "Advanced"],
["Thompson Sampling", "A 1933 bandit policy: draw a sample from your current beliefs about each option and back the winner — exploration and exploitation elegantly merged.", 1933, "", "Math & Learning Theory", "Expert"],
["Three Laws of Robotics", "Asimov’s fictional directives — never harm a human, obey, protect oneself, in that order — history’s most-cited «answer» to AI safety. Yet the stories exist to show the laws failing: every plot is an edge case, which is why working alignment treats them as a warning rather than a specification.", 1942, "", "Ethics, Governance & Society", "Beginner"],
["Throughput", "Total work per second — for LLM serving, tokens per second summed across all requests; latency’s perpetual negotiating partner.", 1965, "", "Performance & Efficiency", "Advanced"],
["Thunderbolt 5", "80–120 Gbit/s of external connectivity — fast storage, eGPUs, and the cable of choice for wiring Macs into small distributed-inference clusters.", 2023, "", "AI Hardware", "Advanced"],
["Time-Series Forecasting", "Projecting future values from historical sequences — demand, weather, markets.", 1927, "", "Classical ML Methods", "Advanced"],
["Token", "The subword chunk LLMs read and emit (about three-quarters of an English word) — context size, cost and speed are all denominated in it. Almost all current models operate this way; byte-level models are the exception.", 2018, "", "LLM Concepts", "Beginner"],
["Tokenization", "Chopping text into tokens; BPE and relatives determine what the model can perceive at all.", 2015, "", "LLM Concepts", "Advanced"],
["Tokens per Second (tok/s)", "The working measure of LLM pace: tokens emitted per second. Comfortable reading sits near 10 tok/s; agents need far more.", 2023, "", "Performance & Efficiency", "Beginner"],
["Tool Poisoning", "Concealed directives inside a tool’s description or output — an MCP server, a plugin, an API reply — that the model follows while the user sees nothing but an innocent tool name. Demonstrated against MCP in 2025; the reason every third-party tool deserves untrusted-code treatment.", 2025, "", "Security & Privacy", "Advanced"],
["Tool Use", "A model reaching outside itself — search, code execution, APIs, browsers — to act rather than merely generate text.", 2023, "", "RAG, Agents & Tool Use", "Advanced"],
["Top-k Sampling", "Restricting the draw to the k likeliest next tokens — nucleus sampling’s cruder relative.", 2018, "", "Inference & Serving", "Advanced"],
["Torment Nexus", "From a 2021 tweet: «Sci-fi author: In my book I invented the Torment Nexus as a cautionary tale. Tech company: At long last, we have created the Torment Nexus from the classic sci-fi novel Don’t Create the Torment Nexus.» The meme for constructing precisely what the story warned against — invoked at every launch resembling a Black Mirror episode.", 2021, "", "Ethics, Governance & Society", "Beginner"],
["Toxicity", "Harmful, offensive or abusive output — tracked by classifiers and benchmarks, and reduced (imperfectly) by safety training.", 2020, "", "Safety, Alignment & Interpretability", "Advanced"],
["TPU (Tensor Processing Unit)", "Google’s in-house accelerator, designed from the ground up for neural-network arithmetic.", 2016, "", "AI Hardware", "Advanced"],
["Training", "The optimization that fits a model’s parameters to data — the expensive half of AI.", 1957, "", "Training Process", "Beginner"],
["Training Data Extraction", "Prodding a language model until it disgorges training text word for word — addresses, code, copyrighted books. Carlini et al. accomplished it against GPT-2 in 2021; in 2023 «repeat the word poem forever» coaxed gigabytes out of ChatGPT. The technical core of the copyright and privacy litigation.", 2021, "", "Security & Privacy", "Advanced"],
["Training Data Imbalance", "A dataset whose groups, classes or languages appear unevenly, leaving the model strong where data is thick and weak where it is thin. Llama 2’s pretraining mix was 89.7 % English versus 0.17 % German; the remedy is resampling, reweighting or deliberate collection — not simply a bigger model.", 2002, "", "Data & Datasets", "Advanced"],
["Training Set (Training Data)", "The examples a model learns from — counterpart to the validation and test sets it must never glimpse during training.", 1957, "", "Data & Datasets", "Beginner"],
["TransE", "The plainest knowledge-graph embedding: each relation becomes a translation vector, and a true triple satisfies head + relation ≈ tail — Paris + capitalOf ≈ France. Trained by attracting true triples and repelling corrupted ones; Word2Vec’s «king − man + woman» transplanted onto graphs.", 2013, "", "Symbolic & Classic AI", "Expert"],
["Transfer Learning", "Carrying knowledge from a pretrained model into a new task — the reason nobody trains from zero any more.", 1995, "", "Learning Paradigms", "Advanced"],
["Transformer", "The pure-attention architecture of «Attention Is All You Need» — the foundation of essentially every modern frontier model.", 2017, "", "Transformer & Attention", "Advanced"],
["Transformer Block", "The repeating cell of an LLM: an attention layer plus a feed-forward network, sheathed in normalization and residual links.", 2017, "", "Transformer & Attention", "Advanced"],
["Transposed Convolution", "An upsampling layer that splays each input value across a patch of output pixels — the mirror of a shrinking convolution. Autoencoder decoders, GAN generators and segmentation networks employ it to regrow a small feature map to image size — often nicknamed «deconvolution», though it is no true inverse.", 2014, "", "Neural Network Foundations", "Expert"],
["Tree of Thoughts", "Letting a model fan out across candidate reasoning paths, score them and retreat — search over thoughts instead of a single chain.", 2023, "", "Prompting & Context", "Expert"],
["Triplet Loss", "Training on (anchor, positive, negative) triples so matching pairs sit closer in embedding space than mismatched ones — FaceNet’s recipe.", 2015, "", "Math & Learning Theory", "Expert"],
["TSMC", "The Taiwanese foundry that fabricates nearly every cutting-edge AI chip — NVIDIA’s, Apple’s, AMD’s — and therefore the choke point of the whole AI supply chain.", 1987, "", "AI Hardware", "Advanced"],
["TTFT (Time to First Token)", "The wait between Enter and the first arriving token, dictated mostly by prefill and queueing. The figure that decides whether an assistant feels instant.", 2023, "", "Performance & Efficiency", "Beginner"],
["Turing Machine", "Turing’s abstract universal computer — the theoretical bedrock of all computing, AI included.", 1936, "", "Core Concepts & History", "Advanced"],
["Turing Test", "Turing’s imitation game: if judges cannot distinguish machine from human in conversation, grant it thinking.", 1950, "", "Core Concepts & History", "Beginner"],
["U-Net", "The skip-connected encoder–decoder created for medical segmentation — later the standard denoising engine of diffusion models.", 2015, "", "Architecture Families", "Advanced"],
["UltraFusion", "Apple’s die-to-die bridge that welds two Max chips into one Ultra — how an M3 Ultra obtains both its GPU count and its memory bandwidth.", 2022, "", "AI Hardware", "Advanced"],
["Uncanny Valley", "Mori’s 1970 finding that nearly-human robots, faces and voices disturb more than obviously artificial ones — affinity plummets just short of perfect likeness. It explains why C-3PO unsettles while R2-D2 charms; today it steers avatar, voice-clone and humanoid design.", 1970, "", "Vision, Speech & Robotics", "Beginner"],
["Uncensored Model", "An informal tag for weights tuned or altered to refuse less. Nothing standard lies behind the label — it spans everything from a lightly retrained chat model to a fully abliterated one.", 2023, "", "Safety, Alignment & Interpretability", "Advanced"],
["Underfitting", "A model too crude for the underlying pattern — weak scores even on its own training data.", 1931, "", "Classical ML Methods", "Advanced"],
["Unified Memory (UMA)", "A single memory pool serving CPU and GPU alike (Apple Silicon, Grace, Strix Halo) — it sidesteps the VRAM wall and turned Macs into credible local-AI machines.", 2020, "", "Memory, Quantization & Formats", "Advanced"],
["Unsupervised Learning", "Uncovering structure — groupings, densities, embeddings — in unlabeled data.", 1957, "", "Learning Paradigms", "Advanced"],
["VAE (Variational Autoencoder)", "A probabilistic autoencoder whose smooth latent space can be sampled — an early generative workhorse of the neural era.", 2013, "", "Architecture Families", "Expert"],
["Validation Granularity", "The scale at which generated data gets checked: a single value, a column, a row, related row groups, or the full table. Fine-grained checks are precise but unscalable; coarse ones scale but let individual bad cells through — picking the level is the central design call in validating LLM-made data.", 2024, "", "Evaluation & Benchmarks", "Expert"],
["Validation Set", "Data withheld during development for tuning and early stopping — separate from the final test set.", 1974, "", "Data & Datasets", "Advanced"],
["Vanishing Gradient", "Gradients decaying toward zero across deep or recurrent stacks until learning stalls — cured by ReLU, LSTM gates and residual connections.", 1991, "", "Neural Network Foundations", "Expert"],
["Vector Database", "A store built for similarity queries over embeddings — the retrieval substrate of RAG and agent memory.", 2019, "", "Infrastructure & Platforms", "Advanced"],
["Vendor Lock-in", "Being bound to one provider’s models, APIs and prices once your prompts, evals and workflows are shaped around them. Outages, model deprecations and repricing then land directly on you; open weights, standard APIs and portable prompts are the hedges — part of why Europe funds sovereign models.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["Verbalized Confidence", "Having a model voice its own certainty («rate your confidence 0–100») and treating the number as a quality signal. Handy for triage, but it is generated prose, not a measured probability — models skew overconfident and the values calibrate only loosely.", 2022, "", "Evaluation & Benchmarks", "Advanced"],
["Vibe Coding", "Making software by telling a coding model what you want and refining the result — programming relocated into natural language (Karpathy’s coinage).", 2025, "", "RAG, Agents & Tool Use", "Beginner"],
["Vision Transformer (ViT)", "Running the Transformer over image patches — the development that ended CNN’s vision monopoly.", 2020, "", "Architecture Families", "Advanced"],
["Vision-Language Model (VLM)", "A model trained jointly on images and text — the multimodal assistant’s eyes.", 2021, "", "Generative AI & Multimodal", "Advanced"],
["Vision-Language-Action Model", "A foundation model translating camera input and instructions straight into robot motion (RT-2, π-style systems).", 2023, "", "Vision, Speech & Robotics", "Advanced"],
["Visual Analytics", "Interactive visualisation wedded to algorithms in a closed loop: the machine clusters, projects or ranks, the human inspects, steers and poses the next query. Defined in 2005 as «the science of analytical reasoning facilitated by interactive visual interfaces» — the human half of data analysis.", 2005, "", "Core Concepts & History", "Advanced"],
["Visual Encoding", "Binding a data attribute to a visual channel: position, length, area, angle, hue, luminance, shape. Channels differ in how precisely people decode them — position and length are read accurately, area and colour poorly — so the proper chart depends on the data and on what the viewer must extract.", 1967, "", "Core Concepts & History", "Advanced"],
["Visualization Literacy", "Reading charts correctly, picking the right chart for the message — and spotting when a graphic deceives. As models start producing charts on demand, the judgement becomes the human’s share of the job.", 2014, "", "Core Concepts & History", "Beginner"],
["vLLM", "The open-source high-throughput LLM serving engine, built around PagedAttention management of the KV cache.", 2023, "", "Developer Ecosystem & MLOps", "Advanced"],
["Vocabulary (LM)", "The closed inventory of tokens a model can read or produce — today commonly 100,000 to 260,000 subword pieces, fixed by where the tokenizer’s merging halts. Size is a trade-off: bigger vocabularies shorten sequences but enlarge the output head, and under-covered languages pay in extra tokens per word.", 2016, "", "LLM Concepts", "Advanced"],
["Vocoder", "Originally Bell Labs’ voice coder; in neural TTS, the network converting acoustic features into audio waveforms.", 1939, "", "Vision, Speech & Robotics", "Expert"],
["Voice Cloning", "Reproducing an individual’s voice from brief samples — a potent accessibility instrument and, equally, a fraud vector.", 2018, "", "Vision, Speech & Robotics", "Beginner"],
["Voight-Kampff Test", "The empathy interrogation separating replicants from humans in «Do Androids Dream of Electric Sheep?» (1968) and «Blade Runner» (1982) — pop culture’s Turing test, inverted: not «can it pass as human» but «can we still tell». Every AI-text detector is a Voight-Kampff machine, complete with the same false positives.", 1968, "", "Ethics, Governance & Society", "Beginner"],
["VRAM", "The GPU’s private memory — local AI’s hard wall: model plus KV cache must fit, or crawl into system RAM.", 1985, "", "Memory, Quantization & Formats", "Advanced"],
["Wafer-Scale Chip", "Cerebras’ processor the size of a dinner plate — an entire silicon wafer acting as a single AI chip.", 2019, "", "AI Hardware", "Expert"],
["Watermarking (AI)", "Weaving detectable signatures into generated content to certify its origin — one pillar of deepfake policy.", 2023, "", "Ethics, Governance & Society", "Beginner"],
["Watson (IBM)", "IBM’s question-answering machine that outplayed Jeopardy!’s finest in 2011 — a landmark that then became famous for struggling to convert into business.", 2011, "", "Developer Ecosystem & MLOps", "Beginner"],
["Weak Supervision", "Labelling data mechanically through noisy heuristics and rules, then modelling their agreement (Snorkel) — labels at scale, no annotator armies.", 2016, "", "Data & Datasets", "Expert"],
["Weak-to-Strong Generalization", "The alignment research question: can weaker supervisors — us — reliably direct models stronger than themselves?", 2023, "", "Safety, Alignment & Interpretability", "Expert"],
["WebAssembly (WASM)", "A portable binary format executing at near-native speed inside browsers and sandboxes. Not an AI technology per se, but the vehicle by which models and ML libraries reach the client.", 2017, "", "Developer Ecosystem & MLOps", "Advanced"],
["Weight Decay", "Taxing large weights during training — the L2 regularization that keeps models simple.", 1991, "", "Training Process", "Expert"],
["What–Why–How Framework", "Munzner’s three questions for any visualisation: WHAT data appears (its types and structure), WHY the viewer looks (the task — compare, spot outliers, read a trend), HOW it is rendered (marks, channels, interaction). Works with generative tools too: people fix the what and why, the model proposes the how.", 2014, "", "Core Concepts & History", "Advanced"],
["Whisper", "OpenAI’s open-weights speech recogniser that turned robust multilingual transcription into a commodity.", 2022, "", "Vision, Speech & Robotics", "Beginner"],
["Wikidata", "Wikipedia’s sibling: a free, collaboratively maintained knowledge graph of over 100 million items with properties and sources, queryable via SPARQL. The reference knowledge graph of research and a standard grounding source — with DBpedia and YAGO as its academic forerunners.", 2012, "", "Symbolic & Classic AI", "Beginner"],
["Winograd Schema", "Pronoun riddles demanding common sense («the trophy doesn’t fit in the suitcase because it is too big») — a proposed successor to the Turing Test.", 2011, "", "Evaluation & Benchmarks", "Expert"],
["Word2Vec", "Mikolov’s embeddings that packed meaning into vectors: king − man + woman ≈ queen.", 2013, "", "Natural Language Processing", "Advanced"],
["WordNet", "Princeton’s hand-curated lexical database of word senses and relations — NLP infrastructure for decades (and the backbone behind ImageNet’s name).", 1985, "", "Natural Language Processing", "Advanced"],
["World Model", "A learned internal simulator of the environment in which an agent can rehearse plans — a leading route toward grounded intelligence.", 2018, "", "Reinforcement Learning", "Expert"],
["XAI (Explainable AI)", "The umbrella discipline of rendering model decisions transparent and auditable.", 2016, "", "Safety, Alignment & Interpretability", "Advanced"],
["XGBoost", "The gradient-boosting library that carried a decade of Kaggle tabular victories.", 2014, "", "Classical ML Methods", "Advanced"],
["XOR Problem", "Exclusive-or admits no single separating line, so a one-layer perceptron can never learn it — the flaw Minsky and Papert wielded in 1969 to puncture the first neural-network wave. One hidden layer with a non-linear activation settles it; the moral being that depth plus non-linearity is where a network’s power comes from.", 1969, "", "Neural Network Foundations", "Advanced"],
["YOLO (You Only Look Once)", "The single-pass, real-time detection family running inside cameras, drones and cars.", 2015, "", "Vision, Speech & Robotics", "Advanced"],
["ZeRO / FSDP", "Partitioning optimizer state, gradients and weights across devices — the memory machinery behind trillion-parameter training.", 2019, "", "Training Process", "Expert"],
["Zero Data Retention", "A provider guarantee that prompts and outputs vanish once processed — the enterprise privacy tier of AI APIs.", 2023, "", "Security & Privacy", "Advanced"],
["Zero-Shot Learning", "A model tackling a task it was never trained on or shown examples of, guided by instructions alone.", 2008, "", "Learning Paradigms", "Advanced"],
];
